insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('hoanauskogl', 'Hoanauskogl', '', '', '', '', 'Hornauskogel', '[{"kategorie": "allg.", "text": "\"dritthöchster Berg im 13. Wiener Gemeindebezirk ([[Hietzing]]) mit einer Höhe von 504 Metern\""}, {"kategorie": "", "text": "Der Hornauskogel liegt im südwestlichen Teil von [[Hietzing]] und gehört zum [[Lainzer]] Tiergarten, einem Teil des [[Wienerwaldes]], der den nordöstlichen Ausläufer der Ostalpen bildet"}, {"kategorie": "", "text": "Etwa 1 Kilometer östlich liegt der [[Kaltbründlberg]], dessen [[Hubertuswarte]] früher in Holzbauweise am [[Hornauskogel]] stand. Im Nordwesten befindet sich der [[Brandberg]]"}, {"kategorie": "", "text": "Am nördlichen Abhang des Hornauskogels entspringen Teile des Quellgebiets des [[Rotwassers]], eines Nebenflusses der Wien"}, {"kategorie": "", "text": "Der Name Hornauskogel wurde erstmals 1788 urkundlich als \"Hurnauskogel k.k. Waldung\" erwähnt und 1819 als Hornauskogl bezeichnet. Der Name leitet sich vom mittelhochdeutschen Begriff \"hornuʒ\" für Hornissen ab, die in dieser Gegend heimisch waren."}]'::jsonb, ''),
  ('hubeatuswartn', 'Hubeatuswartn', '', '', '', '', 'Hubertuswarte', '[{"kategorie": "allg.", "text": "\"Aussichtsturm, der sich auf dem 508 Meter hohen [[Kaltbründlberg]] im [[Lainzer]] Tiergarten in Wien befindet\""}, {"kategorie": "", "text": "Die Aussichtswarte ist nach dem heiligen Hubertus, dem Bischof von Lüttich und Schutzpatron der Jagd, benannt"}, {"kategorie": "", "text": "Während des [[Ersten]] Weltkrieges wurde auf dem Kaltbründlberg ein militärischer Beobachtungsturm errichtet, der jedoch verfiel"}, {"kategorie": "", "text": "Nach dem Krieg, als der [[Lainzer]] Tiergarten der Öffentlichkeit zugänglich gemacht wurde, forderten Besucher einen neuen Aussichtsturm. Im Jahr 1937 wurde schließlich die heutige Hubertuswarte vom Kriegsgeschädigtenfonds errichtet, der den Tiergarten von der Republik Österreich übertragen bekommen hatte"}, {"kategorie": "", "text": "Die Hubertuswarte ist 20,1 Meter hoch (bis zur Aussichtsplattform), wobei die Gesamthöhe 22,4 Meter beträgt"}, {"kategorie": "", "text": "An der Südseite, ebenerdig, befindet sich eine blaue glasierte Tonrelief-Gedenktafel mit einer Inschrift und dem Abbild des heiligen Hubertus. Diese Tafel wurde nach 1945 beschädigt und als Erinnerung an die schwere Zeit in diesem Zustand belassen."}]'::jsonb, ''),
  ('braundbeag', 'Braundbeag', '', '', '', '', 'Brandberg', '[{"kategorie": "allg.", "text": "419 Meter hoher Berg im 13. Wiener Gemeindebezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Der Brandberg liegt im Westen des [[Lainzer]] Tiergartens in der Katastralgemeinde [[Auhof]], nahe der Grenze zur niederösterreichischen Gemeinde Purkersdorf"}, {"kategorie": "", "text": "In seiner Umgebung befinden sich: der [[Johannser]] Kogel im Nordosten und der [[Hornauskogel]] im Südosten. Der Brandberg gehört zum [[Wienerwald]], der den nordöstlichen Ausläufer der Ostalpen bildet"}, {"kategorie": "", "text": "Der Name Brandberg leitet sich vom Flurnamen \"Brand\" ab, der auf ein Waldstück hinweist, das entweder durch einen Waldbrand oder eine Brandrodung entstanden ist"}, {"kategorie": "", "text": "Dieser Flurname ist erstmals 1788 urkundlich belegt. Im Südosten des Berges liegt außerdem die Brandwiese, die ebenfalls auf diesen Ursprung verweist."}]'::jsonb, ''),
  ('hognbeag', 'Hognbeag', '', '', '', '', 'Hagenberg', '[{"kategorie": "allg.", "text": "\"412 Meter hoher, bewaldeter Berg im 13. Wiener Gemeindebezirk ([[Hietzing]]), der zum [[Lainzer]] Tiergarten gehört\""}, {"kategorie": "", "text": "Der Hagenberg liegt im nördlichen Teil von Hietzing, nahe den alten Ortskernen von [[Ober-Sankt-Veit]] und [[Hacking]]. Er ist Teil des [[Wienerwaldgebirges]], das den nordöstlichen Ausläufer der Ostalpen bildet"}, {"kategorie": "", "text": "Im Norden grenzt er an den [[Nikolaiberg]], und im Westen an den [[Johannser]] Kogel. Am Rande des Hagenbergs befindet sich ferner auch der [[Schallautzergraben]], desen Bach als Zubringer in den [[Grünauer]] Bach mündet"}, {"kategorie": "", "text": "Der Name Hagenberg wurde erstmals 1377 als \"Hekenperg\" urkundlich erwähnt. Es wird vermutet, dass der Name nicht vom Wort „Hag“ (Hecke) stammt, sondern sich auf das nahegelegene Dorf [[Hacking]] bezieht"}, {"kategorie": "", "text": "In der Vergangenheit wurden am Hagenberg auch Weingärten erwähnt, die jedoch heute nicht mehr existieren."}]'::jsonb, ''),
  ('hocknbeag', 'Hocknbeag', '', '', '', '', 'Hackenberg', '[{"kategorie": "allg.", "text": "\"306 Meter hoher Berg im Bezirksteil [[Sievering]] des 19. Wiener Gemeindebezirks ([[Döbling]])\""}, {"kategorie": "", "text": "Der Hackenberg wird im Nordosten vom [[Arbesbach]] und im Südwesten vom [[Krottenbach]] umflossen, die heute jedoch als Bachkanäle geführt werden. Die Ausläufer des Hackenbergs erstrecken sich nach Osten bis zur [[Krim]] (Oberdöbling)"}, {"kategorie": "", "text": "Der Hackenberg wurde erstmals 1305 in einer Kaufurkunde für [[Herzog]] Rudolf als „hakkenperge“ erwähnt. Der Name leitet sich vom alten Wiesenmaß \"Haken\" ab"}, {"kategorie": "", "text": "Am südwestlichen Hang des Hackenbergs befand sich im Mittelalter der Ort Chlaintzing, der heute nur noch als Wüstung bekannt ist. Seit 1883 liegt der [[Sieveringer]] Friedhof am südwestlichen Abhang des Hackenbergs"}, {"kategorie": "", "text": "Heute ist der Hackenberggrößtenteils von Kleingartensiedlungen bedeckt, jedoch haben sich auch einige Weingärten erhalten"}, {"kategorie": "", "text": "Unterhalb des Gipfels, in Richtung [[Krottenbachstraße]], befindet sich der Wasserbehälter Hackenberg der Wiener Wasserversorgung."}]'::jsonb, ''),
  ('arbesboch', 'Arbesboch', '', '', '', '', 'Arbesbach', '[{"kategorie": "allg.", "text": "\"Bach im 19. Wiener Gemeindebezirk ([[Döbling]]), der teilweise offen und teilweise als Bachkanal geführt wird (auch \"Erbsenbach\" oder \"Sieveringerbach\" genannt)\""}, {"kategorie": "", "text": "Der etwa 4,3 Kilometer lange Bach ist der wichtigste Nebenfluss des [[Krottenbachs]] und verläuft größtenteils im Bezirksteil [[Sievering]]"}, {"kategorie": "", "text": "Der Arbesbach entspringt im Wienerwald zwischen dem [[Dreimarkstein]] und dem Latisberg ([[Cobenzl]]) und fließt entlang der [[Sieveringer]] Straße. Mehrere Quellarme, wie der Gereutebach, vereinigen sich zum Arbesbach, der schließlich in den [[Krottenbach]] mündet"}, {"kategorie": "", "text": "Im Mittel- und Unterlauf ist der Bach teilweise überbaut oder verrohrt, besonders im dicht besiedelten Gebiet von [[Sievering]], wo er zunehmend in den Bachkanal übergeht"}, {"kategorie": "", "text": "Der Name des Arbesbachs leitet sich vom mittelhochdeutschen Wort \"erbiz\" oder \"arwis\" für \"Erbse\" ab, was auf den früheren Bewuchs des Ufers mit wilden Erbsenpflanzen hinweist"}, {"kategorie": "", "text": "Früher war der Arbesbach ein oft unkontrollierbarer Gebirgsbach, der regelmäßig Überschwemmungen verursachte und zur Abfallentsorgung genutzt wurde. Zwischen 1894 und 1896 begann die Einwölbung des Baches, um die Überschwemmungen und Geruchsbelästigungen zu reduzieren"}, {"kategorie": "", "text": "In den 1950er und 1960er Jahren wurde diese Einwölbung im Ortskern von Sievering weitergeführt."}]'::jsonb, ''),
  ('krottnboch', 'Krottnboch', '', '', '', '', 'Krottenbach', '[{"kategorie": "allg.", "text": "\"Bach im 19. Wiener Gemeindebezirk ([[Döbling]]), dessen Quelle sich an der Grenze zu Niederösterreich bei [[Neustift]] am Walde befindet\""}, {"kategorie": "", "text": "Der Bach verläuft über eine Länge von etwa sieben Kilometern und hat ein Einzugsgebiet von rund elf Quadratkilometern. Er entspringt an den Südseiten des [[Dreimarksteins]] und des [[Michaelerbergs]] im Bereich von [[Salmannsdorf]] und [[Neustift]] am Walde"}, {"kategorie": "", "text": "Ursprünglich markierte der Bach die Grenze zwischen den Wiener Gemeindeteilen [[Oberdöbling]] und [[Unterdöbling]] und wurde von zahlreichen Brücken überspannt. Der wichtigste Zubringer des Krottenbachs ist der [[Arbesbach]], der aus [[Sievering]] kommt"}, {"kategorie": "", "text": "Im Laufe der Zeit wurde der Krottenbach, der zuvor offen durch Döbling floss, zunehmend überbaut. Der Unterlauf wurde bereits 1889 überwölbt, und der Großteil des Oberlaufs folgte 1910/1911"}, {"kategorie": "", "text": "Der Bach ist heute größtenteils ausgetrocknet und fließt nur noch in geringem Umfang. Restbestände des Krottenbachs sind im [[Wertheimsteinpark]] als Teich mit kurzem Abflussgerinne sowie im Oberlauf zwischen dem Quellgebiet und der [[Salmannsdorfer]] Straße sichtbar"}, {"kategorie": "", "text": "Das Verschwinden des Krottenbachs hat das Ortsbild von Döbling erheblich verändert. Früher prägte der Bach eine deutliche Geländestufe zwischen Ober- und Unterdöbling, die heute größtenteils verschwunden ist. An einigen Stellen, wie zwischen der Hofzeile und dem Max-Patat-Weg, ist die alte Geländestufe jedoch noch erkennbar."}]'::jsonb, ''),
  ('weatheimschdaapark', 'Weatheimschdaapark', '', '', '', '', 'Wertheimsteinpark', '[{"kategorie": "allg.", "text": "\"rund 62.500 m² große Parkanlage im Wiener Stadtteil [[Oberdöbling]], gelegen an einem natürlichen Geländeabfall zum [[Donaukanal]]\""}, {"kategorie": "", "text": "Der Park befindet sich östlich der [[Döblinger]] Hauptstraße und fällt steil zur [[Heiligenstädter]] Straße, dem [[Donaukanal]] und der [[Vorortelinie]] ab"}, {"kategorie": "", "text": "Im Park gibt es einen kleinen Teich, der von natürlichen Quellen gespeist wird, was den letzten sichtbaren Rest des früher offen fließenden [[Krottenbachs]] darstellt, der zwischen 1893 und 1930 großteils eingewölbt wurde"}, {"kategorie": "", "text": "Der Park beherbergt viele alte und exotische Pflanzen. Zusätzlich finden sich dort mehrere Denkmäler, darunter: (i) eine Büste des Schriftstellers Ferdinand von Saar (aufgestellt 1914), (ii) ein Denkmal für den Dichter Franz Keim (1924), sowie (iii) eine Büste von Julius Schlegel (1975), der als Retter der Kunstschätze von Montecassino bekannt ist"}, {"kategorie": "", "text": "Der Park wurde ursprünglich als Privatgarten angelegt, als Rudolf von Arthaber, ein Textilfabrikant, 1834/35 die Villa Wertheimstein errichtete. Arthaber ließ hier auch das erste bürgerliche Palmen- und Treibhaus in Österreich bauen"}, {"kategorie": "", "text": "Nach Arthabers Tod kaufte Leopold Ritter von Wertheimstein die Villa und den Park. Seine Familie führte dort einen literarischen Salon, der zu einem geistigen Zentrum Wiens wurde"}, {"kategorie": "", "text": "Franziska von Wertheimstein vermachte die Villa und den Park der Stadt Wien mit der Auflage, den Park als öffentliche Grünfläche zu erhalten. Seit dem 20. Juni 1908 ist der Park für die Öffentlichkeit zugänglich"}, {"kategorie": "", "text": "In der Villa Wertheimstein befindet sich seit 1964 das Bezirksmuseum Döbling sowie ein Weinbaumuseum. Der Park war auch Standort des ersten Blindengartens Mitteleuropas, der 1959 angelegt wurde, dessen Elemente heute aber größtenteils entfernt sind. Ein Eidechsenbiotop wurde 1992 im Park geschaffen."}]'::jsonb, ''),
  ('michaelabeag', 'Michaelabeag', '', '', '', '', 'Michaelerberg', '[{"kategorie": "allg.", "text": "\"387 Meter hoher Berg im 17. Wiener Gemeindebezirk ([[Hernals]]), im nördlichen [[Wienerwald]]\""}, {"kategorie": "", "text": "Der Michaelerberg liegt in Hernals, ist jedoch an drei Seiten vom 18. Bezirk ([[Währing]]) umschlossen. Er ist vollständig mit Eichen-Mischwald bedeckt, wobei besonders die Zerreiche weit verbreitet ist"}, {"kategorie": "", "text": "In der Nähe befindet sich auch der [[Schafberg]], ein weiterer markanter Berg der Umgebung. Am Südhang des Michaelerbergs liegt die Kleingartensiedlung Michaelerwiese"}, {"kategorie": "", "text": "Der Michaelerberg ist ein bewaldeter Hügel, der zur grünen Landschaft des [[Wienerwalds]] zählt und eine wichtige Erholungsfläche für die umliegenden Bezirke darstellt."}]'::jsonb, ''),
  ('veitlissngroom', 'Veitlissngroom', '', '', '', '', 'Veitlissengraben', '[{"kategorie": "allg.", "text": "\"Bach im 13. Wiener Gemeindebezirk ([[Hietzing]]) und ein Zubringer des [[Marienbachs]]\""}, {"kategorie": "", "text": "Der Veitlissengraben hat eine Länge von 770 Metern, entspringt wie der [[Schallautzergraben]] südlich des [[Hagenbergs]] im [[Lainzer]] Tiergarten und fließt in östlicher Richtung"}, {"kategorie": "", "text": "Nachdem er den Lainzer Tiergarten durch einen Durchlass an der Tiergartenmauer beim Adolfstor verlässt, fließt er unter dem Adolfstorsteg (erbaut 1968), einer 6 Meter langen und 2 Meter breiten Fußgängerbrücke, hindurch"}, {"kategorie": "", "text": "Ab der [[Veitlissengasse]] wird der Veitlissengraben als Bachkanal geführt und mündet am Ende der Gasse unterirdisch in den [[Marienbach]]"}, {"kategorie": "", "text": "Der Name Veitlissen ist ein historischer Flurname, der sich aus dem Ortsnamen à(Ober) St. Veit und dem mittelalterlichen Begriff Lüssen ableitet. \"Luß\" (Plural: \"Lüssen\") bezeichnet einen Streifen Land, der während der Besiedlung im Mittelalter einer Adelsfamilie oder einem Kloster per Zufallsverfahren, also mittels Los, zugeteilt wurde."}]'::jsonb, ''),
  ('veitlissngossn', 'Veitlissngossn', '', '', '', '', 'Veitlissengasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]), im Bezirksteil [[Ober-Sankt-Veit]]\""}, {"kategorie": "", "text": "Der Name leitet sich von der historischen Bezeichnung Veitlissen ab, die mit dem Ortsnamen [[St]]. Veit und dem mittelalterlichen Begriff \"Lüssen\" verbunden ist, welcher im Mittelalter für zugeteilte Landstreifen verwendet wurde"}, {"kategorie": "", "text": "\"Luß\" (Plural: \"Lüssen\") bezeichnet einen Streifen Land, der während der Besiedlung im Mittelalter einer Adelsfamilie oder einem Kloster per Zufallsverfahren, also mittels Los, zugeteilt wurde"}, {"kategorie": "", "text": "Entlang der Gasse verläuft der Veitlissengraben, ein Bach, der ab der Veitlissengasse als Bachkanal geführt wird und schließlich in den [[Marienbach]] mündet."}]'::jsonb, ''),
  ('mariinboch', 'Mariinboch', '', '', '', '', 'Marienbach', '[{"kategorie": "allg.", "text": "\"Bach im 13. Wiener Gemeindebezirk ([[Hietzin]])g und ein Zubringer des rechten Wienflusssammelkanals, der teilweise als Bachkanal geführt wird\""}, {"kategorie": "", "text": "Der oberirdische Verlauf des Marienbachs hat eine Länge von 1.240 Metern und eine Höhendifferenz von 149 Metern. Der Bach entspringt auf der Baderwiese im Naturschutzgebiet [[Lainzer]] Tiergarten, nahe dem Aussichtspunkt Wienerblick. Im Naturschutzgebiet ist er ein Trockental, das nur bei Niederschlägen Wasser führt"}, {"kategorie": "", "text": "Nachdem er den Lainzer Tiergarten durch einen Durchlass verlässt, fließt er unter der 2001 errichteten Fußgängerbrücke Hubertustürlsteg und ab der [[Schweizertalstraße]] als unterirdischer Bachkanal. Der Kanal ist 1.440 Meter lang und verläuft unter der Schweizertalstraße, wo er den [[Veitlissengraben]] aufnimmt, sowie unter der [[Firmiangasse]], bevor er in den rechten Wienflusssammelkanal mündet"}, {"kategorie": "", "text": "Der Marienbach floss früher oberirdisch durch die seit dem 12. Jahrhundert bestehende Siedlung [[Ober-Sankt-Veit]]. Sein Verlauf wurde im Ortszentrum mehrmals verändert und begradigt"}, {"kategorie": "", "text": "Der Marienbach sorgte lange für Überschwemmungen, das letzte schwere Hochwasser ereignete sich 1898, bei dem der Durchlass in der [[Tiergartenmauer]] brach und eine Überflutung von Ober-Sankt-Veit ein Todesopfer forderte. Der Ausbau des Bachkanals wurde zwischen 1907 und 1916 abgeschlossen."}]'::jsonb, ''),
  ('tiagoatnmaua', 'Tiagoatnmaua', '', '', '', '', 'Tiergartenmauer', '[{"kategorie": "allg.", "text": "\"historische Mauer, die den [[Lainzer]] Tiergarten im 13. Wiener Gemeindebezirk ([[Hietzing]]) umschließt\""}, {"kategorie": "", "text": "Sie wurde zwischen 1782 und 1787 auf Anordnung von Kaiser [[Josef]] II. erbaut, um das Areal des neu geschaffenen Tiergartens, das verschiedene Wälder und Wiesen umfasste, einzufrieden"}, {"kategorie": "", "text": "Der Bau der Mauer wurde 1772 durch ein Patent von Kaiserin Maria Theresia initiiert und von ihrem Sohn Josef II. umgesetzt. Philipp Schlucker, ein Maurergehilfe, erhielt den Auftrag, die Mauer zu bauen. Sie wurde aus Steinen der Umgebung sowie zugeführten Ziegeln errichtet. Die Mauer hat eine Länge von etwa 24.225 Metern und eine Höhe von 2,3 Metern"}, {"kategorie": "", "text": "Der Bau erfolgte in mehreren Abschnitten, wobei Schlucker von 1782 bis 1787 arbeitete. Teilweise gab es Herausforderungen, wie Schäden an der Mauer und Probleme mit der Finanzierung, die zu Verzögerungen führten. Trotz der Schwierigkeiten wurde die Mauer fertiggestellt und dient seither als Begrenzung des Lainzer Tiergartens"}, {"kategorie": "", "text": "Die Tiergartenmauer hat die Funktion, den Lainzer Tiergarten, der als kaiserliches Jagdrevier diente, zu schützen. Sie ist ein bedeutendes Bauwerk der Wiener Stadtgeschichte und erfordert bis heute regelmäßige Renovierungen. Teile der ursprünglichen Mauer sind an einigen Stellen noch erkennbar"}, {"kategorie": "", "text": "Die Bezeichnung „Armer Schlucker“ wird oft auf den Baumeister Philipp Schlucker zurückgeführt, der für seinen bescheidenen Lebensstil bekannt war, obwohl der Begriff aber schon vor seiner Zeit existierte."}]'::jsonb, ''),
  ('schweizatoischdrossn', 'Schweizatoischdrossn', '', '', '', '', 'Schweizertalstraße', '[{"kategorie": "allg.", "text": "eine der ältesten Straßen im Wiener Bezirksteil [[Ober-Sankt-Veit]], im 13. Gemeindebezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Der Name „Schweizertalstraße“ stammt von der umgangssprachlichen Bezeichnung für Milchmeier (=Milchbauer bzw. Melker), die Anfang des 20. Jahrhunderts in dieser Gegend zahlreich angesiedelt waren. Ursprünglich hieß die Straße einfach nur „Schweizertal“"}, {"kategorie": "", "text": "Die Straße ist etwa 0,8 Kilometer lang und beginnt bei der Erzbischofgasse in Ober-Sankt-Veit. Entlang der Schweizertalstraße münden mehrere Gassen ein, darunter die [[Veitlissengasse]], die Hentschelgasse, die Winzerstraße, der Mariensteig, die Matrasgasse, und die Prehausergasse"}, {"kategorie": "", "text": "Die Schweizertalstraße war früher ein Zentrum für Gastronomiebetriebe mit großen Gastgärten. Hier befanden sich unter anderem das Winzerhaus von August Puraner und die Gastwirtschaft Heinrichshof, die heute Wohngebäuden gewichen sind"}, {"kategorie": "", "text": "Heute ist die Schweizertalstraße eine ruhige Wohnstraße, geprägt von Wohnhäusern und früheren Villen. Eine der Villen auf der Höhe des Mariensteigs war sogar einmal als Bundespräsidentenvilla im Gespräch."}]'::jsonb, ''),
  ('firmiangossn', 'Firmiangossn', '', '', '', '', 'Firmiangasse', '[{"kategorie": "allg.", "text": "\"historische Straße im 13. Wiener Gemeindebezirk ([[Hietzing]]), im Bezirksteil [[Ober-Sankt-Veit]]\""}, {"kategorie": "", "text": "Die Firmiangasse führt vom [[Wolfrathplatz]] am oberen Ende der [[Hietzinger]] Hauptstraße, wo das [[Ober-Sankt-Veiter]] Schloss steht, bergab bis zum [[Hietzinger]] Kai am rechten Ufer des [[Wienflusses]]"}, {"kategorie": "", "text": "Die Straße wurde am 10. Juli 1894 nach dem Fürsterzbischof Leopold Maximilian Graf Firmian benannt. Zuvor trug sie den Namen Lange Gasse"}, {"kategorie": "", "text": "Leopold Maximilian Graf Firmian (*11. Oktober 1766, †29. November 1831) war von 1822 bis 1831 Fürsterzbischof von Wien. Er stammte aus einer bedeutenden Südtiroler Adelsfamilie und war zuvor Bischof von Lavant und Administrator von Salzburg. In Wien förderte er die Pfarrerbildung, die Leopoldinenstiftung für Missionsarbeit und gründete die erste Kleinkinder-Bewahranstalt. Firmian starb 1831 und wurde im Stephansdom beigesetzt"}, {"kategorie": "", "text": "Fürsterzbischof Firmian ließ das Schloss in Ober St. Veit während des Biedermeier restaurieren, und es diente lange Zeit als Sommerresidenz der Wiener Erzbischöfe"}, {"kategorie": "", "text": "Das Ensemble rund um die Firmiangasse, einschließlich der parallel verlaufenden Glasauergasse, erinnert noch stark an die dörfliche Struktur des früheren [[Ober]] Sankt-Veit, bevor der Bezirk 1892 nach Wien eingemeindet wurde."}]'::jsonb, ''),
  ('nikolaibeag', 'Nikolaibeag', '', '', '', '', 'Nikolaiberg', '[{"kategorie": "allg.", "text": "\"273 Meter hoher Hügel im 13. Wiener Gemeindebezirk ([[Hietzing]]), der sich über das [[Wiental]] erhebt\""}, {"kategorie": "", "text": "Der Nikolaiberg liegt im nördlichen Teil von Hietzing, am nordöstlichen Rand des [[Lainzer]] Tiergartens. Im Norden wird er von der Wien ([[Wienfluss]]) begrenzt, im Süden schließt der [[Hagenberg]] an. Am Südwesthang befindet sich die Hackinger Wiese, und im Südosten liegt die Nikolaiwiese mit der gleichnamigen [[Nikolaikapelle]]"}, {"kategorie": "", "text": "Unter einem Teil des Nikolaibergs verläuft der Lainzer Tunnel der Westbahn"}, {"kategorie": "", "text": "Der Nikolaiberg wurde erstmals 1788 urkundlich erwähnt und ist nach der [[Nikolaikapelle]] benannt, die am Osthang des Berges liegt"}, {"kategorie": "", "text": "Die Kapelle selbst wurde bereits 1321 urkundlich erwähnt und gehörte lange zur Pfarre Hütteldorf. Sie wurde teilweise im romanischen Stil erbaut und kam 1833 gemeinsam mit dem umliegenden Gebiet zum [[Lainzer]] Tiergarten."}]'::jsonb, ''),
  ('wiinflussbruckn', 'Wiinflussbruckn', '', '', '', '', 'Wienflussbrücken', '[{"kategorie": "allg.", "text": "\"Fußgänger-, Straßen- und Bahnbrücken, die den Wienfluss innerhalb des Stadtgebiets überspannen\""}, {"kategorie": "", "text": "Diese Brücken sind nicht nur technische Bauwerke, sondern auch Zeugnisse der Wiener Stadtgeschichte und Architektur, vor allem im Zusammenhang mit der [[Wienflussregulierung]] gegen Ende des 19. Jahrhunderts"}, {"kategorie": "", "text": "Die Geschichte der Wienflussbrücken reicht bis in die Römerzeit zurück, als erste hölzerne Brücken den Fluss überquerten. Während des Mittelalters und der Babenbergerzeit wurden an strategischen Orten, wie am heutigen [[Karlsplatz]] oder beim [[Stubentor]], Brücken errichtet. Diese Brücken bildeten wichtige Verbindungspunkte für Handelsstraßen, die Wien mit Italien und Ungarn verbanden"}, {"kategorie": "", "text": "Im 19. Jahrhundert, besonders nach der Eingemeindung der Vorstädte 1850, wurden zahlreiche neue Brücken errichtet oder bestehende Holzbrücken durch robustere Konstruktionen ersetzt. Dies geschah im Kontext der zunehmenden Urbanisierung und dem wachsenden Bedarf an Infrastruktur für den städtischen Verkehr"}, {"kategorie": "", "text": "Besonders die [[Wienflussregulierung]] von 1895 bis 1903 war ein einschneidendes Projekt, bei dem der Fluss reguliert und zahlreiche neue Brücken gebaut wurden. Architekten wie Friedrich Ohmann und Josef Hackhofer prägten den Brückenbau im Wiener Jugendstil. Viele der Brücken dieser Zeit wurden mit künstlerischen Elementen wie Skulpturen oder dekorativen Eisengeländern ausgestattet"}, {"kategorie": "", "text": "Wichtige Wienflussbrücken sind beispielsweise (i) die [[Stubenbrücke]] (Wollzeile/Landstraßer Hauptstraße), (ii) die [[Radetzkybrücke]] (Franz-Josefs-Kai/Radetzkystraße), (iii) die [[Pilgrambrücke]] (Pilgramgasse/Hofmühlgasse), (iv) die [[Kennedybrücke]] (Hietzinger Hauptstraße/Hadikgasse), (v) die [[Margaretengürtelbrücke]] (Margaretengürtel/Gumpendorfer Gürtel), (vi) die [[Schönbrunnerbrücke]] (Grünbergstraße/Winckelmannstraße), (vii) die [[Nevillebrücke]] (Nevillegasse/Brückengasse), (viii) die [[Reinprechtsdorfer]] Brücke (Reinprechtsdorfer Straße/Anilingasse), (ix) der [[Zollamtssteg]] (Stubenring/Hauptzollamt), (x) die [[Baumgartenbrücke]] (Hietzinger Kai/Hadikgasse), (xi) die [[Guldenbrücke]] (Hietzinger Kai/Guldengasse), (xii) die [[Auhofbrücke]] (Wientalstraße/Linzer Straße), (xii) die [[Bräuhausbrücke]] (Bergmillergasse/Stampfergasse), (xiii) die [[Hütteldorfer]] Brücke (Brudermanngasse/Rußpekgasse), (xiv) [[Lobkowitzbrücke]] (Linke Wienzeile/Schönbrunner Straße), (xv) [[Magdalenenbrücke]] (Steggasse/Linke Wienzeile), (xvi) [[Marxerbrücke]] (Stubenring/Marxergasse), (xvii) [[Schönbrunner]] Schlossbrücke (Schönbrunner Schlossstraße), (xviii) [[Stadtparkbrücke]] (Stadtpark/Am Heumarkt), (xix) [[Sankt-Veit-Brücke]] (Hietzinger Kai/Hochsatzengasse), (xx) [[Stiegerbrücke]] (Stiegergasse/Längenfeldgasse), (xxi) [[Ungerbrücke]] (Stadtpark/Ungargasse), (xxii) [[Wackenroder]] Brücke (Morizgasse/St. Johann-Gasse), (xxiii) [[Zufferbrücke]] (Hackinger Kai/Hackinger Straße), sowie (xxiv) Paul-Amann-Brücke (Astgasse/Fleschgasse)."}]'::jsonb, ''),
  ('hackingaschdrossn', 'Hackingaschdrossn', '', '', '', '', 'Hackinger Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 14. Wiener Gemeindebezirk ([[Penzing]]), die durch die Stadtteile [[Hacking]], [[Oberbaumgarten]] und [[Unterbaumgarten]] verläuft\""}, {"kategorie": "", "text": "Die Straße wurde am 10. Juli 1894 nach dem ehemaligen Vorort Hacking benannt, um dessen Namen zu bewahren"}, {"kategorie": "", "text": "Hacking war einst eine eigenständige Gemeinde, die später in die Stadt Wien eingemeindet wurde. Der Name Hacking selbst wurde erstmals 1156 als Hacingen erwähnt, und leitet sich von Markwardus de Hacingen, einem Gefolgsmann des Markgrafen Heinrich II. von Babenberg, ab"}, {"kategorie": "", "text": "Historisch gesehen, entstand Hacking am Hang des Hackinger Berges, der heute als [[Hagenberg]] bekannt ist, unterhalb der Hackinger Burg, die erstmals im 13. Jahrhundert erwähnt wurde"}, {"kategorie": "", "text": "Die Hackinger Straße hat im Laufe der Zeit verschiedene Namen getragen. So war ein Teil der Straße früher als Hackinger Kai, Alleegasse in Hacking und An der Wien in Baumgarten bekannt, bevor sie 1894 zur heutigen Hackinger Straße umbenannt wurde"}, {"kategorie": "", "text": "Die Hackinger Straße ist somit nicht nur eine wichtige Verkehrsverbindung, sondern trägt auch historische Bedeutung, indem sie an die Geschichte des ehemaligen Vororts und dessen Bedeutung für die Entwicklung des heutigen Wiener Stadtgebiets erinnert."}]'::jsonb, ''),
  ('obabaumgoatn', 'Obabaumgoatn', '', '', '', '', 'Oberbaumgarten', '[{"kategorie": "allg.", "text": "\"Katastralgemeinde im 14. Wiener Gemeindebezirk ([[Penzing]]), im westlichen Teil Wiens, etwa sieben Kilometer vom Stadtzentrum entfernt\""}, {"kategorie": "", "text": "Geografisch befindet sich Oberbaumgarten auf der nördlichen Seite des [[Wienflusses]] und grenzt im Norden und Westen an den Stadtteil [[Hütteldorf]]. Im Süden grenzt es an die in [[Hietzing]] (13. Bezirk) befindlichen Bezirksteile [[Hacking]] und Ober-Sankt-Veit, die auf der anderen, südlichen Seite des Wienflusses liegen"}, {"kategorie": "", "text": "Oberbaumgarten ist, gemeinsam mit [[Unterbaumgarten]], ein Teil des Wiener Stadtteils [[Baumgarten]], der aufgrund seiner Lage im Wiener Westen dem 14. Bezirk ([[Penzing]]) zugeordnet ist"}, {"kategorie": "", "text": "Baumgarten und seine Katastralgemeinden bilden einen Bezirksteil, der eine Mischung aus Wohngebieten und städtischer Infrastruktur aufweist. Ein markantes Bauwerk in Oberbaumgarten ist die [[Oberbaumgartner]] Kirche, ein zentraler Ort im Stadtteil"}, {"kategorie": "", "text": "Mit einer Fläche von 89,85 Hektar umfasst die Katastralgemeinde Oberbaumgarten ein bedeutendes Areal im Bezirk, das sich durch seine Lage und seine Anbindung an den westlichen Wiener Stadtrand auszeichnet."}]'::jsonb, ''),
  ('untabaumgoatn', 'Untabaumgoatn', '', '', '', '', 'Unterbaumgarten', '[{"kategorie": "allg.", "text": "\"Katastralgemeinde im 14. Wiener Gemeindebezirk ([[Penzing]]), die - zusammen mit [[Oberbaumgarten]] - den Bezirksteil [[Baumgarten]] bildet\""}, {"kategorie": "", "text": "Geografisch liegt Unterbaumgarten auf der linken, nördlichen Seite des [[Wienflusses]] und erstreckt sich über eine Fläche von 102,21 Hektar, von denen etwa drei Hektar jenseits des Wienflusses im benachbarten Bezirk [[Hietzing]] (13. Bezirk) liegen"}, {"kategorie": "", "text": "Unterbaumgarten grenzt im Norden an den [[Flötzersteig]] und an den Bezirksteil [[Hütteldorf]], im Nordosten an [[Breitensee]], im Osten an den Bezirksteil Oberbaumgarten und im Süden, auf der anderen Seite des Wienflusses, an [[Unter-Sankt-Veit]] im 13. Bezirk ([[Hietzing]])"}, {"kategorie": "", "text": "[[Baumgarten]], das rund sieben Kilometer westlich des Stadtzentrums von Wien liegt, gehört zum westlichen Teil der Stadt. Unterbaumgarten ist somit ein integraler Bestandteil des Wiener Westens und zeichnet sich durch seine Nähe zu anderen bedeutenden Stadtteilen aus."}]'::jsonb, ''),
  ('brutalismus', 'Brutalismus', '', '', '', '', 'Brutalismus', '[{"kategorie": "allg.", "text": "\"\"Architekturrichtung, die in den 1950er Jahren entstand und ihren Höhepunkt in den 1960er und 1970er Jahren erreichte\""}, {"kategorie": "", "text": "Der Begriff leitet sich vom französischen „béton brut“ ab, was „roher Beton“ bedeutet, und beschreibt den charakteristischen Baustil, der für seine massiven, rohen Oberflächen bekannt ist"}, {"kategorie": "", "text": "Brutalistische Gebäude zeichnen sich durch ihre ehrliche Verwendung von Materialien, vor allem Sichtbeton, und durch die oft monumentalen, klobigen Formen aus"}, {"kategorie": "", "text": "Brutalistische Gebäude sind weltweit zu finden, insbesondere in Universitäten, sozialen Wohnungsbauten und Regierungsgebäuden, aber auch Kirchen. Ein Beispiel für ein brutalistisches Kirchengebäude in Wien ist u.a. die [[Oberbaumgartner]] Kirche"}, {"kategorie": "", "text": "Obwohl der Brutalismus in den 1960er und 1970er Jahren sehr populär war, wurde er in späteren Jahrzehnten oft kritisiert. Die rohen, massiven Gebäude galten vielen als unattraktiv und wurden als kalt oder brutal empfunden"}, {"kategorie": "", "text": "Dennoch erlebte der Stil in den letzten Jahren eine gewisse Wiederentdeckung und Wertschätzung, besonders von Architekturliebhabern, die seine Ehrlichkeit und Ausdruckskraft schätzen."}]'::jsonb, ''),
  ('neoromanik', 'Neoromanik', '', '', '', '', 'Neoromanik', '[{"kategorie": "", "text": "Sie war Teil der sogenannten „Neostile“ oder à„Historismus“-Bewegungen, bei denen ältere architektonische Epochen romantisiert und in einem modernen Kontext wiederbelebt wurden"}, {"kategorie": "", "text": "Merkmale der Neuromantik in der Architektur sind: (i) Rundbögen und romanische Fensterformen, (ii) massive Baukörper (dicke Wände, blockhafte Formen), (iii) einfache geometrische Formen (wie Würfel und Rechtecke, im Gegensatz zu den verspielteren und verschnörkelten Formen derà Gotik oder des [[Barock]]),  (iv) Säulen und Arkaden,  (v) Turmformen und Zwillings- oder Drillingsfenster"}, {"kategorie": "", "text": "In Wien ist die Neuromantik unter anderem bei Kirchenbauten zu finden, wie etwa bei der [[Baumgartner]] Pfarrkirche im 14. Wiener Gemeindebezirk (Penzing)"}, {"kategorie": "", "text": "Die Neuromantik war Teil eines allgemeinen Trends, der in der Architektur, Kunst und Literatur im 19. Jahrhundert zu beobachten war, als man versuchte, die Stile vergangener Epochen wiederzubeleben und zu modernisieren."}]'::jsonb, ''),
  ('neiromanik', 'Neiromanik', '', '', '', '', 'Neuromanik', '[{"kategorie": "", "text": "Sie war Teil der sogenannten „Neostile“ oder à„Historismus“-Bewegungen, bei denen ältere architektonische Epochen romantisiert und in einem modernen Kontext wiederbelebt wurden"}, {"kategorie": "", "text": "Merkmale der Neuromantik in der Architektur sind: (i) Rundbögen und romanische Fensterformen, (ii) massive Baukörper (dicke Wände, blockhafte Formen), (iii) einfache geometrische Formen (wie Würfel und Rechtecke, im Gegensatz zu den verspielteren und verschnörkelten Formen derà Gotik oder des [[Barock]]),  (iv) Säulen und Arkaden,  (v) Turmformen und Zwillings- oder Drillingsfenster"}, {"kategorie": "", "text": "In Wien ist die Neuromantik unter anderem bei Kirchenbauten zu finden, wie etwa bei der [[Baumgartner]] Pfarrkirche im 14. Wiener Gemeindebezirk (Penzing)"}, {"kategorie": "", "text": "Die Neuromantik war Teil eines allgemeinen Trends, der in der Architektur, Kunst und Literatur im 19. Jahrhundert zu beobachten war, als man versuchte, die Stile vergangener Epochen wiederzubeleben und zu modernisieren."}]'::jsonb, ''),
  ('heimatstil', 'Heimatstil', '', '', '', '', 'Heimatstil', '[{"kategorie": "arch.", "text": "\"architektonische und kunsthandwerkliche Strömung, die sich im späten 19. und frühen 20. Jahrhundert entwickelte\""}, {"kategorie": "", "text": "Der Heimatstil entstand als Reaktion auf die Industrialisierung und den damit verbundenen Verlust regionaler Traditionen und wurde oft als Versuch gesehen, eine \"rückbesinnende\" Bauweise zu fördern, die lokale, volkstümliche und traditionelle Architekturelemente betont. Der Heimatstil war besonders in Deutschland, Österreich und der Schweiz verbreitet"}, {"kategorie": "", "text": "Merkmale des Heimatstils: (i) regionaltypische Bauformen (z.B. Fachwerkbauten, Schindeldächer oder verputzte Wände);  (ii) natürliche Baumaterialien (Holz, Stein und Ziegel);  (iii) Einfachheit und Bodenständigkeit (Verzierungen sind oft zurückhaltend und funktional, im Gegensatz zum opulenten [[Historismus]] oder den verspielten Formen des [[Jugendstils]]);  (iv) steile Satteldächer oder Walmdächer sowie ausladende Balkone, die oft mit regionalen Schnitzereien oder Ornamenten verziert sind;  (v) symmetrisch angeordnete Fenster und Türen mit klaren, geometrischen Formen (auch kleine Sprossenfenster oder Fensterläden sind häufig im Heimatstil zu finden)"}, {"kategorie": "", "text": "In Österreich war der Heimatstil ebenfalls populär, insbesondere in Vororten oder ländlichen Gebieten. Ein Beispiel ist die Architektur von Wohngebäuden oder Kirchen im frühen 20. Jahrhundert, die regionale Bauelemente betonten (siehe [[Pfarrkirche Baumgarten]])"}]'::jsonb, ''),
  ('gotik', 'Gotik', '', '', '', 'Wiener Architektur & Baukunst', 'Gotik', '[{"kategorie": "allg.", "text": "\"kunstgeschichtliche Epoche, die im 12. Jahrhundert in Frankreich entstand und bis ins 16. Jahrhundert in Europa verbreitet war\""}, {"kategorie": "", "text": "Sie löste die [[Romanik]] ab und wurde später ihrerseits von der [[Renaissance]] abgelöst. Die Gotik ist vor allem durch ihre monumentale Sakralarchitektur bekannt, die den himmelwärts strebenden, religiösen Charakter betonte"}, {"kategorie": "", "text": "Merkmale der Gotik: (i) Spitzbögen (zentrales gestalterisches Element in der gotischen Architektur), (ii) filigrane [[Rippengewölbe]] (statt des massiven, romanischen Tonnengewölbes);  (iii) Strebewerk (System aus Strebepfeilern und Strebebögen, das die Last nach außen ableitet und somit größere Fensterflächen erlaubt);  (iv) Große Fenster und Maßwerk (farbenprächtigen Glasfenster, oft in Form von [[Rosetten]], die viel Licht ins Innere lassen, sowie eine kunstvolle Gestaltung der Fensteröffnungen);  (v) Hohe Türme und [[Fialen]] (spitz zulaufende Türmchen);  (vi) Das bekannteste Bauwerk der Gotik in Wien ist der [[Stephansdom]] (auch à„Steffl“ genannt) ist . Er steht im Zentrum der Stadt und ist das Wahrzeichen von Wien. Der Bau des Doms begann im 12. Jahrhundert, doch das heutige gotische Erscheinungsbild entstand hauptsächlich ab dem 14. Jahrhundert. Besonders prägnant sind der hohe Südturm, die beeindruckenden gotischen Fenster und das kunstvolle Maßwerk."}]'::jsonb, ''),
  ('barock', 'Barock', '', '', '', 'Wiener Architektur & Baukunst', 'Barock', '[{"kategorie": "allg.", "text": "\"kunstgeschichtliche Epoche, die sich vom späten 16. Jahrhundert bis ins 18. Jahrhundert erstreckte\""}, {"kategorie": "", "text": "Ursprünglich in Italien entstanden, breitete sich der Barock über ganz Europa aus und prägte Architektur, Malerei, Musik und Literatur"}, {"kategorie": "", "text": "Merkmale des Barock: (i) Dynamik und Bewegung (im Gegensatz zur statischen Symmetrie der [[Renaissance]] betonte der Barock Bewegung und Dramatik, oft durch geschwungene Linien und komplexe Formen);  (ii) Prachtentfaltung und Opulenz (barocke Gebäude sind oft reich verziert, mit aufwendigen Fassaden, Säulen, Stuckarbeiten und Deckengemälden. Das Ziel war, Macht, Reichtum und den göttlichen Einfluss zu demonstrieren);  (iii) Symmetrie und Monumentalität (trotz der Betonung von Dynamik sind barocke Gebäude häufig streng symmetrisch aufgebaut, oft mit zentralen Kuppeln oder beeindruckenden Treppenhäusern);  (iv) Spiel mit Licht und Schatten (barocke Architektur setzt oft auf dramatische Licht- und Schatteneffekte, um den Betrachter in Staunen zu versetzen und die Wirkung des Gebäudes zu verstärken);  (v) Verbindung von Architektur, Malerei und Skulptur (im Barock sind die Künste eng miteinander verwoben. Die Decken- und Wandmalereien sowie Skulpturen sind oft integraler Bestandteil der Architektur)"}, {"kategorie": "", "text": "Der [[Schönbrunner]] Schlosskomplex ist das bekannteste Barockbauwerk in Wien. Er diente als Sommerresidenz der [[Habsburger]] und wurde im 17. Jahrhundert im Stil des Barock umgebaut. Das Schloss selbst, die prachtvollen Gartenanlagen und der berühmte [[Neptunbrunnen]] spiegeln die Opulenz und Monumentalität des Barock wider. Die Anlage steht auf der UNESCO-Welterbeliste und ist ein Symbol für die Prachtentfaltung der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Ein weiteres wichtiges Beispiel ist die [[Karlskirche]], die eine ikonische barocke Kirche Wiens darstellt, erbaut im 18. Jahrhundert nach einem Entwurf von Johann Bernhard Fischer von Erlach"}]'::jsonb, ''),
  ('biedameia', 'Biedameia', '', '', '', 'Wiener Stadtgeschichte', 'Biedermeier', '[{"kategorie": "allg.", "text": "\"kulturelle und gesellschaftliche Epoche im deutschsprachigen Raum, die etwa den Zeitraum zwischen dem [[Wiener]] Kongress (1815) und der [[Revolution]] von 1848 umfasst\""}, {"kategorie": "", "text": "Der Begriff \"Biedermeier\" beschreibt Stilrichtungen in Kunst, Literatur, Architektur, Musik, Innenraumgestaltung und Alltagskultur, die vom bürgerlichen Lebensideal, Privatheit und einer konservativen Rückzugsmentalität geprägt sind"}, {"kategorie": "", "text": "Der Wiener Kongress im Jahr 1815 markierte das Ende der napoleonischen Kriege und den Beginn der Restaurationsepoche unter [[Metternich]] (1815–1848 - eine Zeit politischer Repression, Zensur, Überwachung und konservativer Ordnung). Als Reaktion hierauf zog sich die Gesellschaft ins Private, Häusliche und Familiäre zurück. Die \"große Welt\" (Politik) wurde als gefährlich empfunden – das individuelle Glück rückte in den Vordergrund"}, {"kategorie": "", "text": "Der Begriff „Biedermeier“ wurde ursprünglich spöttisch verwendet, abgeleitet von der fiktiven Figur \"Gottlieb Biedermeier\", einem gutmütigen, unpolitischen Spießbürger aus satirischen Gedichten (publiziert in den 1850er-Jahren). Später wurde der Begriff neutralisiert und kunsthistorisch etabliert"}, {"kategorie": "", "text": "Bekannte Künstler der Biedermeierzeit sind u.a. die Maler Carl Spitzweg (malerische Ironie des Kleinbürgertums) und Ferdinand Georg Waldmüller (realistische Porträts, Landschaften), die Autoren Adalbert Stifter (Erzählungen, Novellen und Romane) und Franz Grillparzer (Theater und Novellen), sowie der Komponist Franz Schubert (Liederzyklen, Klaviermusik)"}, {"kategorie": "", "text": "In der Architektur markiert das Biedermeier den Übergang vom [[Klassizismus]] zum [[Historismus]] (schlichte Fassaden, oft mit klaren Symmetrien und wenig Ornament). Noch heute sind viele Biedermeierhäuser in Wien erhalten, besonders in [[Spittelberg]], [[Josefstadt]], [[Alsergrund]] und [[Gumpendorf]])"}, {"kategorie": "", "text": "Wien war eines der Zentren des Biedermeiers - einer Epoche der Innerlichkeit, Häuslichkeit und bürgerlichen Beschaulichkeit in einer Zeit politischer Unsicherheit. Das Biedermeier steht für schlichte Eleganz, kunstvolle Zurückhaltung und den Versuch, das Glück im Privaten zu finden. Heute wird Biedermeier sowohl als Stilbegriff (z. B. für Möbel oder Malerei) als auch als historische Geisteshaltung verstanden."}]'::jsonb, ''),
  ('romanik', 'Romanik', '', '', '', '', 'Romanik', '[{"kategorie": "allg.", "text": "\"Epoche der europäischen Kunst und Architektur, die ungefähr vom 10. bis zum 12. Jahrhundert dauerte\""}, {"kategorie": "", "text": "Die Romanik gilt als die erste überregionale Kunstepoche des Mittelalters und ist geprägt von massiven, robusten Bauwerken mit klaren und einfachen Formen"}, {"kategorie": "", "text": "Merkmale der Romanik: (i) massive Bauweise (dicke Mauern, kleine Fenster und eine eher gedrungene, solide Bauweise);  (ii) Rundbögen (in Fenstern, Türen und Arkaden);  (iii) Gewölbedecken (Verwendung von [[Tonnengewölben]] oder [[Kreuzgratgewölben]] zur Überdachung von Innenräumen);  (iv) Symmetrie und Klarheit (symmetrischer Aufbau, schlicht und monumental);  (iv) Weniger Verzierungen (im Vergleich zur späteren [[Gotik]] ist die Romanik sparsamer bei der Verwendung von Skulpturen und Verzierungen. Diese finden sich vor allem an Portalen und Kapitellen)"}, {"kategorie": "", "text": "In Wien gibt es nur wenige vollständig erhaltene Bauwerke aus der Romanik, da viele Gebäude im Laufe der Jahrhunderte umgebaut oder im gotischen Stil überarbeitet wurden. Dennoch finden sich noch einige bedeutende romanische Elemente und Bauten aus der Zeit, wie zum Beispiel die [[Ruprechtskirche]], die älteste erhaltene Kirche Wiens"}, {"kategorie": "", "text": "Die Ruprechtskirche wurde vermutlich im 11. oder frühen 12. Jahrhundert erbaut. Die Kirche weist noch einige romanische Merkmale auf, wie zum Beispiel die Rundbogenfenster im unteren Teil des Turms. Im Inneren findet sich eine römische Spolie, die in die Bauweise integriert wurde"}, {"kategorie": "", "text": "Auch der Stephansdom, der zwar hauptsächlich ein gotisches Bauwerk ist, hat noch bedeutende romanische Elemente, vor allem an der Westfassade. Die beiden sogenannten Heidentürme (auf der Westseite des Doms, romanisch geprägt) und das Riesentor (Hauptportal des Stephansdoms mit seinem charakteristischen Rundbogen) stammen aus der romanischen Bauphase des Doms (12. Jahrhundert)."}]'::jsonb, ''),
  ('neigotik', 'Neigotik', '', '', '', '', 'Neugotik', '[{"kategorie": "arch.", "text": "\"architektonischer Stil des 19. Jahrhunderts, der sich an der mittelalterlichen Gotik orientiert und deren charakteristische Merkmale wie spitzbogige Fenster, steile Dächer, filigrane Türme und reich verzierte Fassaden wieder aufgreift\""}, {"kategorie": "", "text": "Der Neugotik-Stil entstand im Zuge der [[Romantik]], als man die Architektur des Mittelalters als Ausdruck von Nationalbewusstsein und historischer Kontinuität neu entdeckte. Dieser Stil wurde vor allem für Kirchen, Rathäuser und Universitätsgebäude verwendet"}, {"kategorie": "", "text": "Merkmale der Neugotik: (i) Spitzbögen und steile Dächer, (ii) reiche Dekoration (insbesondere mit [[Fialen]] und [[Maßwerk]]), (iii) Vertikalität und Streben nach Höhe, (iv) Fensterrose oder Maßwerkfenster, (v) Verwendung von Grundmaterialien wie Stein, oft in Kombination mit neueren Techniken und Baustoffen des 19. Jahrhunderts"}, {"kategorie": "", "text": "In Wien ist das [[Wiener]] Rathaus das bekannteste und bedeutendste Bauwerk im neugotischen Stil. Es wurde von 1872 bis 1883 nach den Plänen des Architekten Friedrich von Schmidt erbaut. Das Wiener [[Rathaus]] zeichnet sich durch seine filigranen Türme, den hohen mittleren Turm mit dem bekannten [[Rathausmann]] und die spitzbogigen Fenster aus. Die Fassade ist reich verziert und erinnert stark an mittelalterliche gotische Kathedralen"}, {"kategorie": "", "text": "Das Wiener Rathaus gilt als herausragendes Beispiel der Neugotik und prägt das Stadtbild Wiens mit seiner imposanten Architektur."}]'::jsonb, ''),
  ('neogotik', 'Neogotik', '', '', '', '', 'Neogotik', '[{"kategorie": "", "text": "Der Neugotik-Stil entstand im Zuge der [[Romantik]], als man die Architektur des Mittelalters als Ausdruck von Nationalbewusstsein und historischer Kontinuität neu entdeckte. Dieser Stil wurde vor allem für Kirchen, Rathäuser und Universitätsgebäude verwendet"}, {"kategorie": "", "text": "Merkmale der Neugotik: (i) Spitzbögen und steile Dächer, (ii) reiche Dekoration (insbesondere mit [[Fialen]] und [[Maßwerk]]), (iii) Vertikalität und Streben nach Höhe, (iv) Fensterrose oder Maßwerkfenster, (v) Verwendung von Grundmaterialien wie Stein, oft in Kombination mit neueren Techniken und Baustoffen des 19. Jahrhunderts"}, {"kategorie": "", "text": "In Wien ist das [[Wiener]] Rathaus das bekannteste und bedeutendste Bauwerk im neugotischen Stil. Es wurde von 1872 bis 1883 nach den Plänen des Architekten Friedrich von Schmidt erbaut. Das Wiener [[Rathaus]] zeichnet sich durch seine filigranen Türme, den hohen mittleren Turm mit dem bekannten [[Rathausmann]] und die spitzbogigen Fenster aus. Die Fassade ist reich verziert und erinnert stark an mittelalterliche gotische Kathedralen"}, {"kategorie": "", "text": "Das Wiener Rathaus gilt als herausragendes Beispiel der Neugotik und prägt das Stadtbild Wiens mit seiner imposanten Architektur."}]'::jsonb, ''),
  ('fiale', 'Fiale', '', '', '', '', 'Fiale', '[{"kategorie": "arch.", "text": "\"spitz zulaufendes, turmartiges Bauelement in der [[gotischen]] und [[neugotischen]] Architektur, das oft zur Verzierung von Gebäuden dient\""}, {"kategorie": "", "text": "Es besteht in der Regel aus einer schlanken, steinernen Struktur, die auf Strebepfeilern, Türmen oder anderen architektonischen Elementen angebracht wird"}, {"kategorie": "", "text": "Fialen sind häufig reich mit Verzierungen wie [[Krabben]] (ornamentalen Zacken) und [[Kreuzblumen]] (blütenartige Abschlussstücke) geschmückt"}, {"kategorie": "", "text": "Funktionen der Fiale: (i) dekorative Funktion (sie unterstreichen die vertikale Ausrichtung eines Bauwerks und betonen die filigrane und himmelstrebende Wirkung, die typisch für die Gotik ist), (ii) konstruktive Funktion (sie tragen zur Stabilisierung von Strebepfeilern bei, da sie das Gewicht auf diese Elemente verlagern und somit die seitliche Ausdehnung von [[Gewölben]] unterstützen)"}, {"kategorie": "", "text": "In der Architektur berühmter gotischer Kathedralen wie dem [[Wiener]] Stephansdom oder dem [[Wiener]] Rathaus sind Fialen wichtige Gestaltungselemente."}]'::jsonb, ''),
  ('wimpeag', 'Wimpeag', '', '', '', '', 'Wimperg', '[{"kategorie": "arch.", "text": "\"dekoratives Bauelement der gotischen Architektur, das als spitz zulaufender, meist dreieckiger Ziergiebel über Portalen, Fenstern oder Nischen angebracht ist\""}, {"kategorie": "", "text": "Wimperge haben häufig eine filigrane, reich verzierte Gestaltung, die oft mit [[Maßwerk]], [[Krabben]] und [[Fialen]] kombiniert ist"}, {"kategorie": "", "text": "Sie betonen die Vertikalität und Dynamik des Bauwerks und verleihen ihm eine zusätzliche Höhe und Leichtigkeit"}, {"kategorie": "", "text": "Typische Merkmale des Wimpergs sind: (i) Spitzbogenform (der Wimperg läuft in einem steilen, spitzen Bogen aus), (ii) Verzierung (Wimperge sind oft mit dekorativen Elementen wie [[Krabben]] und [[Fialen]] sowie einer [[Kreuzblume]] als Abschluss an der Spitze versehen), (iii) Maßwerk (oft findet sich in der Fläche des Wimpergs ein durchbrochenes [[Maßwerk]], das der Struktur weitere filigrane Details hinzufügt)"}, {"kategorie": "", "text": "Ein berühmtes Beispiel für den Einsatz von Wimpergen in Wien ist die [[Votivkirche]], die im neugotischen Stil erbaut wurde und an vielen Fenstern und Portalen Wimperge aufweist."}]'::jsonb, ''),
  ('kreizbluman', 'Kreizbluman', '', '', '', '', 'Kreuzblume', '[{"kategorie": "arch.", "text": "\"dekoratives Element der gotischen Architektur, das häufig als krönender Abschluss auf [[Wimpergen]], [[Fialen]] oder anderen spitzen Bauteilen zu finden ist\""}, {"kategorie": "", "text": "Sie besteht aus einem symmetrisch gestalteten, blüten- oder kreuzartigen Ornament, das in der Regel aus vier stilisierten Blättern oder Blütenblättern besteht, die kreuzförmig angeordnet sind"}, {"kategorie": "", "text": "Merkmale der Kreuzblume: (i) kreuzförmige Anordnung (die Blätter oder Blütenblätter sind gleichmäßig um eine Mittelachse gruppiert und formen ein Kreuz), (ii) Zierfunktion (Kreuzblumen haben eine rein dekorative Funktion und werden häufig an den Spitzen gotischer Bauwerke angebracht), (iii) Symbolik (die Form der Kreuzblume kann christliche Symbole wie das Kreuz oder die Blume der Reinheit aufgreifen)"}, {"kategorie": "", "text": "Ein typisches Beispiel für die Verwendung von Kreuzblumen in Wien ist der [[Stephansdom]], bei dem diese Ornamente die Spitzen der Fialen und Wimperge zieren."}]'::jsonb, ''),
  ('maassweak', 'Maassweak', '', '', '', '', 'Maßwerk', '[{"kategorie": "arch.", "text": "\"gestalterisches Element der [[gotischen]] Architektur, das vor allem zur Verzierung von Fenstern, Balustraden und anderen baulichen Öffnungen verwendet wird\""}, {"kategorie": "", "text": "Es besteht aus geometrischen, meist symmetrischen Formen, die durch feine Steinstrukturen entstehen. Typische Formen des Maßwerks sind Kreise, Bögen, [[Dreipässe]] und [[Vierpässe]], die in regelmäßigen Mustern angeordnet sind"}, {"kategorie": "", "text": "Merkmale des Maßwerks: (i) geometrische Formen (Kreise, Dreiecke, Pässe [[[Dreipass]], [[Vierpass]]], [[Rosetten]] und [[Lanzettenformen]]),  (ii) Verwendung bei Fenstern (besonders charakteristisch ist das Maßwerk in gotischen Kirchenfenstern, wo es die oberen Bereiche der Fenster in kunstvollen Mustern füllt),  (iii) Material (das Maßwerk wird aus dünnen Steinrippen gebildet, die den Rahmen für farbige Glasfenster oder offene Balustraden geben),  (iv) ästhetische Funktion (das Maßwerk verleiht Gebäuden Leichtigkeit und Eleganz und betont die filigrane und himmelstrebende Wirkung der gotischen Bauweise)"}, {"kategorie": "", "text": "Ein berühmtes Beispiel für Maßwerk in Wien ist die Fassade des [[Stephansdoms]], wo das Maßwerk die Fenster und weitere Bauelemente schmückt."}]'::jsonb, ''),
  ('dreipass', 'Dreipass', '', '', '', '', 'Dreipass', '[{"kategorie": "arch.", "text": "\"dekoratives Element der gotischen Architektur, das aus drei gleichmäßig geschwungenen, kreisförmigen Bögen besteht, die zusammen ein symmetrisches Muster bilden\""}, {"kategorie": "", "text": "Es wird oft im Rahmen von Fenstern, Portalverzierungen oder Balustraden als Teil des [[Maßwerks]] verwendet"}, {"kategorie": "", "text": "Der Dreipass symbolisiert häufig die [[Heilige]] Dreifaltigkeit und war besonders in der [[Gotik]] ein beliebtes Gestaltungselement"}, {"kategorie": "", "text": "Merkmale des Dreipasses: (i) drei Bögen (der Dreipass besteht aus drei Bögen, die aneinander anschließen und einen gemeinsamen Umriss bilden), (ii) symmetrische Anordnung (die Bögen sind gleichmäßig angeordnet und fügen sich harmonisch in das [[Maßwerk]] ein), (iii) Verwendung (häufig bei Fenstern und Balustraden in gotischen Kirchen und Kathedralen zu finden)"}, {"kategorie": "", "text": "Ein typisches Bauwerk in Wien, in dem der Dreipass prominent verwendet wird, ist der [[Stephansdom]]. Besonders in den gotischen Fenstern und im Maßwerk der Türme des Doms sind Dreipass-Muster zu finden. Diese Fenster tragen zur charakteristischen filigranen und himmelstrebenden Ästhetik des Stephansdoms bei"}, {"kategorie": "", "text": "Auch die [[Votivkirche]] in Wien ist ein bedeutendes Beispiel für die Verwendung des Dreipass im Maßwerk. Die Votivkirche, die im [[neugotischen]] Stil erbaut wurde, zeigt viele typische Elemente der [[Gotik]], einschließlich des [[Maßwerks]], das reich an Dreipässen, [[Vierpässen]] und anderen ornamentalen Formen ist. Besonders in den Fenstern der Votivkirche kann man das filigrane Maßwerk mit Dreipass-Mustern gut erkennen."}]'::jsonb, ''),
  ('viapass', 'Viapass', '', '', '', '', 'Vierpass', '[{"kategorie": "arch.", "text": "\"dekoratives Gestaltungselement der [[gotischen]] Architektur, bei dem vier kreisförmige Bögen miteinander verbunden sind und ein Kleeblatt-ähnliches Muster bilden\""}, {"kategorie": "", "text": "Es ist eine Form des [[Maßwerks]], das oft in Fenstern, [[Rosetten]] und anderen ornamentalen Details von gotischen und neugotischen Bauwerken zu finden ist"}, {"kategorie": "", "text": "In Wien sind die [[Votivkirche]] und der [[Stephansdom]] typische Beispiele, in denen Vierpässe prominent im Maßwerk verwendet werden"}, {"kategorie": "", "text": "Votivkirche: Diese [[neugotische]] Kirche, die im 19. Jahrhundert erbaut wurde, zeigt viele Fenster und Fassadenelemente mit Maßwerk, in denen Vierpass-Muster vorkommen. Die Fenster der Votivkirche sind reich mit gotischen Ornamenten versehen, zu denen der Vierpass gehört"}, {"kategorie": "", "text": "Stephansdom: Auch am berühmten Wiener Wahrzeichen Stephansdom, einem gotischen Bauwerk, findet sich Maßwerk mit Vierpässen in den Fenstern und dekorativen Details"}, {"kategorie": "", "text": "Der Vierpass ist ein typisches Ornament in der [[Gotik]] und [[Neugotik]], das zur Verzierung und Strukturierung großer Fensterflächen verwendet wurde."}]'::jsonb, ''),
  ('rosettn', 'Rosettn', '', '', '', '', 'Rosette', '[{"kategorie": "arch.", "text": "\"rundes Fenster, das häufig in der [[gotischen]] Architektur verwendet wird und durch kompliziertes [[Maßwerk]] in Form eines stilisierten Blütenmusters geprägt ist\""}, {"kategorie": "", "text": "Die Rosette ist besonders charakteristisch für Kirchenfassaden und verleiht diesen eine ornamentale und spirituelle Bedeutung, indem sie Licht in die Innenräume lenkt und gleichzeitig eine aufwendige ästhetische Funktion erfüllt"}, {"kategorie": "", "text": "In Wien sind zwei berühmte Bauwerke besonders für ihre Rosettenfenster bekannt: die [[Votivkirche]] ([[neugotische]] Kirche) besitzt beeindruckende Rosettenfenster, die an den Hauptfassaden zu finden sind"}, {"kategorie": "", "text": "Das [[Wiener]] Rathaus, das ebenfalls im neugotischen Stil errichtet wurde, zeigt an seiner Fassade mehrere Rosettenfenster, die an die gotische Architektur anknüpfen. Besonders am zentralen Turm sowie an den großen Fenstern der Fassade sind diese dekorativen Elemente zu finden"}, {"kategorie": "", "text": "Rosetten sind prägende architektonische Details in [[gotischen]] und [[neugotischen]] Kirchen und symbolisieren häufig die himmlische Vollkommenheit und göttliche Ordnung."}]'::jsonb, ''),
  ('fenstarosettn', 'Fenstarosettn', '', '', '', '', 'Fensterrosette', '[{"kategorie": "arch.", "text": "\"kreisrundes Fenster, das meist mit kunstvollem [[Maßwerk]] gefüllt ist und häufig in der [[gotischen]] und [[neugotischen]] Architektur vorkommt\""}, {"kategorie": "", "text": "Die Rosettenfenster sind oft zentral in Kirchenfassaden oder Giebeln zu finden und dienen sowohl einem dekorativen als auch einem symbolischen Zweck"}, {"kategorie": "", "text": "Typisch für Rosetten ist die aufwändige Gestaltung des inneren Fensterrahmens, der in Blumen- oder Sternformen unterteilt ist. Diese Fenstergestaltung lässt Licht in faszinierenden Mustern in den Innenraum fließen"}, {"kategorie": "", "text": "Ein berühmtes Beispiel für Fensterrosetten in Wien ist die Votivkirche, die an ihrer Westfassade eine prächtige Rosette im neugotischen Stil besitzt"}]'::jsonb, ''),
  ('lanzettn', 'Lanzettn', '', '', '', '', 'Lanzette', '[{"kategorie": "arch.", "text": "\"hohes, schlankes, spitzbogiges Fenster oder ein Bogenelement, das besonders in der [[gotischen]] Architektur verwendet wird\""}, {"kategorie": "", "text": "Der Begriff leitet sich von der Form einer Lanze ab, da das Fenster an eine aufrechte Lanze erinnert"}, {"kategorie": "", "text": "[[Lanzettfenster]] sind oft paarweise oder in Gruppen angeordnet und mit [[Maßwerk]] verziert, was in gotischen Kirchenbauten besonders typisch ist"}, {"kategorie": "", "text": "Ein Beispiel für den Einsatz von Lanzetten findet sich in der [[Votivkirche]] in Wien, deren Fassade von zahlreichen Lanzettfenstern geprägt ist"}, {"kategorie": "", "text": "Diese schlanken Spitzbogenfenster betonen die vertikale Ausrichtung der gotischen Architektur und tragen zur filigranen Gestaltung der Kirchenfassade bei."}]'::jsonb, ''),
  ('lanzettfensta', 'Lanzettfensta', '', '', '', '', 'Lanzettfenster', '[{"kategorie": "arch.", "text": "\"hohes, schlankes, spitzbogiges Fenster oder ein Bogenelement, das besonders in der [[gotischen]] Architektur verwendet wird\""}, {"kategorie": "", "text": "Der Begriff leitet sich von der Form einer Lanze ab, da das Fenster an eine aufrechte Lanze erinnert"}, {"kategorie": "", "text": "[[Lanzettfenster]] sind oft paarweise oder in Gruppen angeordnet und mit [[Maßwerk]] verziert, was in gotischen Kirchenbauten besonders typisch ist"}, {"kategorie": "", "text": "Ein Beispiel für den Einsatz von Lanzetten findet sich in der [[Votivkirche]] in Wien, deren Fassade von zahlreichen Lanzettfenstern geprägt ist"}, {"kategorie": "", "text": "Diese schlanken Spitzbogenfenster betonen die vertikale Ausrichtung der gotischen Architektur und tragen zur filigranen Gestaltung der Kirchenfassade bei."}]'::jsonb, ''),
  ('rippngwoelb', 'Rippngwölb', '', '', '', '', 'Rippengewölbe', '[{"kategorie": "arch.", "text": "\"spezifische Form des Gewölbes, bei der die Lasten durch sichtbare, steinerne Rippen getragen werden\""}, {"kategorie": "", "text": "Diese Rippen sind die tragenden Elemente, während die Gewölbeflächen (die sogenannten Kappen) meist aus leichterem Material gefertigt werden"}, {"kategorie": "", "text": "Das Rippengewölbe ermöglicht es, den Raum effizienter zu überspannen und gleichmäßige Lastverteilung zu gewährleisten"}, {"kategorie": "", "text": "Das Rippengewölbe ist ein prägendes Merkmal der [[gotischen]] Architektur, das vor allem in Kirchen und Kathedralen Verwendung fand. Die Rippen verlaufen typischerweise in Bögen, die sich in einem geometrischen Muster über dem Raum kreuzen und sich in den Schlüsselstein des Gewölbes treffen"}, {"kategorie": "", "text": "Berühmte Beispiele für Rippengewölbe in Wien sind der [[Stephansdom]] und die [[Votivkirche]]. Hier findet man beeindruckende Rippengewölbe im Inneren, die den hohen Kirchenraum überspannen und das majestätische Erscheinungsbild des Baus unterstreichen."}]'::jsonb, ''),
  ('kreizrippngwoelb', 'Kreizrippngwölb', '', '', '', '', 'Kreuzrippengewölbe', '[{"kategorie": "arch.", "text": "\"Weiterentwicklung des [[Rippengewölbes]], das aus der [[Gotik]] stammt\""}, {"kategorie": "", "text": "Es besteht aus zwei sich kreuzenden [[Tonnengewölben]], deren Last von sogenannten \"Rippen\" getragen wird"}, {"kategorie": "", "text": "Diese Rippen bilden die tragenden Strukturen des Gewölbes und sind typischerweise an den [[Gewölbekappen]] sichtbar"}, {"kategorie": "", "text": "Das Kreuzrippengewölbe ermöglicht eine bessere Lastverteilung und flexiblere Konstruktionen, da die Kappen leichter ausgeführt werden können"}, {"kategorie": "", "text": "Ein markantes Merkmal des Kreuzrippengewölbes ist die kreuzförmige Anordnung der Rippen, die sich in einem gemeinsamen Scheitelpunkt (dem Schlussstein) treffen. Dieses Gewölbesystem ermöglichte größere Spannweiten und wurde besonders in gotischen Kirchen verwendet"}, {"kategorie": "", "text": "Berühmte Beispiele für Kreuzrippengewölbe in Wien sind der [[Stephansdom]] (vor allem im Langhaus der Kathedrale) und die [[Votivkirche]]. Hier findet man beeindruckende Kreuzrippengewölbe im Inneren, die den hohen Kirchenraum überspannen und das majestätische Erscheinungsbild des Baus unterstreichen. Die eleganten, sich kreuzenden Rippen betonen die Höhe des Raumes und geben dem Bau seine charakteristische gotische Struktur."}]'::jsonb, ''),
  ('tonnangwoelb', 'Tonnangwölb', '', '', '', '', 'Tonnengewölbe', '[{"kategorie": "arch.", "text": "\"einfache, halbzylindrische Gewölbeform, die aussieht wie ein längs durchgeschnittener Hohlzylinder\""}, {"kategorie": "", "text": "Es erstreckt sich über den gesamten Raum und wird oft durch parallel verlaufende Seitenwände gestützt"}, {"kategorie": "", "text": "Diese Bauweise gehört zu den ältesten Gewölbearten und wurde bereits in der Antike, insbesondere von den Römern, häufig verwendet"}, {"kategorie": "", "text": "Das Tonnengewölbe verteilt die Last des Daches oder darüberliegender Strukturen gleichmäßig entlang der Wände"}, {"kategorie": "", "text": "Es besitzt keine komplexen Tragstrukturen wie Rippen (siehe [[Kreuzrippengewölbe]]), sondern leitet die Last durch seine geschlossene, halbrunde Form ab"}, {"kategorie": "", "text": "Diese Gewölbeform wurde oft in langen, schmalen Räumen eingesetzt, wie in Kirchen oder Gängen"}, {"kategorie": "", "text": "Ein Beispiel für ein Tonnengewölbe in Wien ist der [[Stephansdom]], der in verschiedenen Teilen seines Baus noch Reste von romanischen Tonnengewölben aufweist, vor allem in den frühesten Abschnitten."}]'::jsonb, ''),
  ('gewoelbekoppn', 'Gewölbekoppn', '', '', '', '', 'Gewölbekappe', '[{"kategorie": "arch.", "text": "\"einzelnes, abgeschlossenes Segment eines [[Gewölbes]], das zwischen den tragenden [[Rippen]] oder anderen Stützelementen eingespannt ist\""}, {"kategorie": "", "text": "In der Regel handelt es sich um eine kleinere Fläche oder einen Abschnitt, der zwischen den Rippen eines [[Kreuzrippengewölbes]] oder [[Kuppelgewölbes]] ausgefüllt wird"}, {"kategorie": "", "text": "Gewölbekappen werden oft als gewölbte Flächen aus Ziegeln oder Steinen konstruiert, die in einem geometrischen Muster zwischen den tragenden Rippen aufgespannt werden"}, {"kategorie": "", "text": "Sie dienen der statischen Funktion, die Lasten der darüberliegenden Strukturen auf die tragenden Elemente (Rippen oder Wände) zu verteilen"}, {"kategorie": "", "text": "Die Form und Größe der Gewölbekappen hängt von der Art des Gewölbes ab. In einem [[Kreuzrippengewölbe]], wie es in gotischen Kirchenbauten (wie beispielsweise der [[Votivkirche]] oder dem [[Stephansdom]]) typisch ist, fügen sich die Kappen elegant zwischen die Kreuzrippen ein und verleihen der Decke ihre dekorative und statische Struktur."}]'::jsonb, ''),
  ('rippn', 'Rippn', '', '', '', '', 'Rippe', '[{"kategorie": "arch.", "text": "\"strukturelles oder dekoratives Bauelement, das insbesondere in [[Gewölben]] vorkommt\""}, {"kategorie": "", "text": "Eine Rippe dient als Verstärkung und Gliederung des Gewölbes und übernimmt dabei sowohl eine tragende als auch eine ästhetische Funktion"}, {"kategorie": "", "text": "Rippen sind vor allem in [[gotischen]] Bauwerken ein zentrales Element, insbesondere im [[Kreuzrippengewölbe]], bei dem sich zwei oder mehr Rippen kreuzen und den Raum in [[Gewölbekappen]] unterteilen"}, {"kategorie": "", "text": "Die Rippen leiten die Last des Gewölbes auf die Stützelemente, wie Pfeiler oder Wände, ab, was es ermöglicht, größere und höhere Räume zu schaffen. Zudem geben sie dem Gewölbe eine rhythmische Struktur und betonen dessen Geometrie"}, {"kategorie": "", "text": "Rippen bestehen häufig aus Stein oder Ziegel und können auch reich verziert sein. Sie prägen das Erscheinungsbild vieler gotischer Kirchen, wie zum Beispiel im [[Wiener]] Stephansdom oder in der [[Votivkirche]]."}]'::jsonb, ''),
  ('gwoelb', 'Gwölb', '', '', '', '', 'Gewölbe', '[{"kategorie": "arch.", "text": "\"bogenförmige Konstruktion, die dazu dient, einen Raum zu überspannen und Lasten gleichmäßig auf Mauern oder Pfeiler abzuleiten\""}, {"kategorie": "", "text": "Es ist eine tragende architektonische Struktur, die besonders in der antiken, mittelalterlichen und [[gotischen]] Baukunst verwendet wurde. Gewölbe sind vor allem in Kirchen, Kathedralen, Burgen und Brücken zu finden"}, {"kategorie": "", "text": "Gewölbe bestehen typischerweise aus Stein, Ziegel oder Beton und ersetzen flache Decken oder Balken, indem sie den Druck durch die gekrümmte Form abfangen. Sie erlauben es, große Räume ohne zusätzliche Stützbalken oder Träger zu überspannen, was in monumentalen Bauwerken besonders wichtig ist"}, {"kategorie": "", "text": "Es gibt verschiedene Arten von Gewölben, darunter: (i) [[Tonnengewölbe]] (eine einfache, halbkreisförmige Wölbung, die wie eine liegende Tonne geformt ist),  (ii) [[Kreuzgewölbe]] (entsteht durch die Überlagerung zweier Tonnengewölbe),  (iii) [[Kreuzrippengewölbe]] (bei gotischen Bauwerken häufig, mit [[Rippen]] als Verstärkung der Gewölbedecken)"}, {"kategorie": "", "text": "In Wien sind viele bedeutende Bauwerke mit Gewölben versehen, darunter der [[Stephansdom]], die [[Votivkirche]] und das [[Wiener]] Rathaus, deren Kreuzrippengewölbe typisch für die gotische Architektur ist."}]'::jsonb, ''),
  ('kupplgwoelb', 'Kupplgwölb', '', '', '', '', 'Kuppelgewölbe', '[{"kategorie": "arch.", "text": "\"besondere Form des Gewölbes, das eine halbkugelförmige Struktur aufweist und oft zur Überdachung großer, zentraler Räume verwendet wird\""}, {"kategorie": "", "text": "Das Kupüpelgewölbe basiert auf dem Prinzip des Kreisbogens und verteilt die Last gleichmäßig auf die tragenden Wände oder Säulen"}, {"kategorie": "", "text": "Kuppeln sind häufig in der Architektur von Kirchen, Moscheen, Palästen und öffentlichen Gebäuden zu finden"}, {"kategorie": "", "text": "Die Konstruktion eines Kuppelgewölbes erfolgt durch die Rotation eines Bogens um seine eigene Mittelachse, was zu einer gleichmäßig gewölbten, meist symmetrischen Form führt"}, {"kategorie": "", "text": "Kuppeln können sowohl auf runden als auch auf polygonalen Grundrissen errichtet werden und sind oft mit aufwendigen Verzierungen oder Laternen versehen, um zusätzliches Licht in das Innere des Gebäudes zu lassen"}, {"kategorie": "", "text": "Ein berühmtes Beispiel für ein Kuppelgewölbe in Wien ist die [[Karlskirche]], deren markante barocke Kuppel das Stadtbild prägt."}]'::jsonb, ''),
  ('kreizgwoelb', 'Kreizgwölb', '', '', '', '', 'Kreuzgewölbe', '[{"kategorie": "arch.", "text": "\"architektonische Gewölbeform, die entsteht, wenn zwei [[Tonnengewölbe]] gleicher Höhe sich rechtwinklig überkreuzen\""}, {"kategorie": "", "text": "An den Schnittlinien der beiden Gewölbe entstehen charakteristische diagonale [[Rippen]] oder Grate, die das Gewicht des Gewölbes auf die vier Ecken oder Pfeiler ableiten"}, {"kategorie": "", "text": "Diese Gewölbeform ist besonders in der [[gotischen]] Architektur weit verbreitet, da das Kreuzgewölbe sowohl Stabilität bietet als auch größere Spannweiten und flexiblere Raumaufteilungen ermöglicht. Es war eine beliebte Lösung für die Überdachung von großen Kirchenschiffen, Kreuzgängen und anderen großen Räumen"}, {"kategorie": "", "text": "Ein bekanntes Beispiel für Kreuzgewölbe in Wien ist der gotische [[Kreuzgang]] des [[Stephansdoms]]."}]'::jsonb, ''),
  ('kreizgaung', 'Kreizgaung', '', '', '', '', 'Kreuzgang', '[{"kategorie": "arch.", "text": "\"architektonischer Bestandteil von Klosteranlagen, Kirchen oder Kathedralen, der als überdachter, meist quadratischer [[Wandelgang]] um einen Innenhof oder einen Garten herum verläuft\""}, {"kategorie": "", "text": "Der Kreuzgang ist in der Regel auf allen Seiten von [[Arkaden]] oder Säulenreihen gesäumt, die den Innenhof umschließen"}, {"kategorie": "", "text": "Ursprünglich diente er als Verbindungsgang zwischen verschiedenen Bereichen des Klosters oder der Kirche, wie der Kirche selbst, dem Refektorium (Speisesaal), den Zellen und anderen wichtigen Räumen"}, {"kategorie": "", "text": "Der Kreuzgang war nicht nur ein funktionaler Durchgang, sondern auch ein Ort der Meditation, Stille und des Gebets für die Mönche oder Ordensleute. Seine quadratische Form symbolisierte die Vollkommenheit und das geschlossene, geistliche Leben in einem Kloster"}, {"kategorie": "", "text": "Ein berühmtes Beispiel für einen Kreuzgang in Wien ist der Kreuzgang des [[Schottenstifts]] oder des [[Stephansdoms]]."}]'::jsonb, ''),
  ('arkaadn', 'Arkaadn', '', '', '', '', 'Arkade', '[{"kategorie": "arch.", "text": "\"architektonische Struktur, bei der eine Reihe von Bögen von Säulen oder Pfeilern getragen wird\""}, {"kategorie": "", "text": "Diese Bögen können entweder Teil eines Ganges, einer Fassade oder einer Überdachung sein"}, {"kategorie": "", "text": "Arkaden sind oft ein dekoratives Element in der Architektur, das gleichzeitig funktional ist, da sie Durchgänge, Terrassen oder überdachte Wege bilden. Sie kommen in vielen Baustilen vor, darunter in der à Romanik, [[Gotik]] und [[Renaissance]]"}, {"kategorie": "", "text": "Arkaden können sowohl im Außenbereich, zum Beispiel in Stadtmauern oder Gebäudefassaden, als auch im Innenbereich, etwa in [[Kreuzgängen]] von Klöstern oder in Innenhöfen, verwendet werden"}, {"kategorie": "", "text": "Ein bekanntes Beispiel für Arkaden in Wien sind die Arkaden des [[Rathausplatzes]], der [[Universität]] Wien oder die des [[Schlosses]] Schönbrunn."}]'::jsonb, ''),
  ('waundlgaung', 'Waundlgaung', '', '', '', '', 'Wandelgang', '[{"kategorie": "arch.", "text": "\"überdachter Gang, der oft an den Außenwänden von Gebäuden oder um Innenhöfe herum verläuft\""}, {"kategorie": "", "text": "Er dient als geschützter Durchgang und ermöglicht es, sich bei schlechtem Wetter oder bei starker Sonneneinstrahlung geschützt zu bewegen"}, {"kategorie": "", "text": "Wandelgänge sind häufig in Klöstern, Palästen oder großen Residenzen zu finden und sind oft mit [[Arkaden]] oder Säulenreihen gestaltet"}, {"kategorie": "", "text": "Wandelgänge können sowohl im Innen- als auch im Außenbereich von Bauwerken vorkommen und verleihen Gebäuden eine elegante und repräsentative Wirkung"}, {"kategorie": "", "text": "Ein Beispiel für einen Wandelgang in Wien ist der [[Kreuzgang]] im Stephansdom, der als überdachter Durchgang innerhalb des Doms dient."}]'::jsonb, ''),
  ('spaetgotik', 'Spätgotik', '', '', '', '', 'Spätgotik', '[{"kategorie": "arch.", "text": "\"letzte Phase der gotischen Architektur und Kunst, die etwa von der Mitte des 14. Jahrhunderts bis in das 16. Jahrhundert andauerte\""}, {"kategorie": "", "text": "Diese Epoche zeichnet sich durch eine zunehmende Verfeinerung und Komplexität der gotischen Stilelemente aus"}, {"kategorie": "", "text": "Typische Merkmale der Spätgotik sind eine besonders ausgeprägte Detailfreude, filigrane Strukturen und komplexe Formen. Der Übergang zur [[Renaissance]] wurde oft fließend gestaltet, wobei dann mitunter Elemente beider Stile kombiniert wurden"}, {"kategorie": "", "text": "Merkmale der Spätgotik: (i) raffinierte [[Maßwerke]] (diese werden vor allem in Fenstern und Fassaden immer komplexer und feiner), (ii) reiche Ornamentik (Verzierungen werden zunehmend aufwändiger, darunter [[Fialen]], [[Wimperge]] und [[Kreuzblumen]]), (iii) Höhepunkt der Gewölbekonstruktion (in der Spätgotik wurden komplizierte Gewölbestrukturen wie [[Netz-]] und [[Sterngewölbe]] sowie filigrane [[Rippengewölbe]] entwickelt), (iv) schlanke, hohe Strukturen (Kirchen und Kathedralen streben noch stärker nach Höhe und wirken oft leicht und transparent), (v) Plastizität (Verzierungen an Fassaden und Innenräumen wurden plastischer und lebendiger gestaltet)"}, {"kategorie": "", "text": "Der [[Stephansdom]] ist eines der markantesten spätgotischen Bauwerke in Wien, insbesondere mit seinem Nordturm und der filigranen Gestaltung des Chors. Obwohl der Bau des Doms über viele Jahrhunderte hinweg erfolgte, spiegelt sein östlicher Teil typische spätgotische Merkmale wider."}]'::jsonb, ''),
  ('netzgwoelb', 'Netzgwölb', '', '', '', '', 'Netzgewölbe', '[{"kategorie": "arch.", "text": "\"spezielle Form des [[Kreuzrippengewölbes]], das sich durch ein dekoratives, netzartiges Muster der [[Rippen]] auszeichnet\""}, {"kategorie": "", "text": "Diese Art des Gewölbes besteht aus sich kreuzenden und vielfach verzweigten Rippen, die das Erscheinungsbild eines Netzes oder einer Fischgräte ergeben"}, {"kategorie": "", "text": "Das Netzgewölbe wurde vor allem in der [[Spätgotik]] verwendet und ist für seine filigrane, oft ornamentale Gestaltung bekannt"}, {"kategorie": "", "text": "Merkmale des Netzgewölbes: (i) Rippenstruktur (die Rippen sind in einem regelmäßigen Muster über die Gewölbefläche verteilt und kreuzen sich an vielen Stellen), (ii) dekorative Funktion (im Gegensatz zu früheren Gewölbetypen, bei denen die Rippen hauptsächlich eine tragende Funktion hatten, dienen die Rippen beim Netzgewölbe vor allem der Dekoration), (iii) flache Wölbung (Netzgewölbe wirken oft weniger stark gewölbt als frühere Gewölbeformen, wodurch sie den Raum optisch erweitern und aufhellen), (iv) Komplexität (Netzgewölbe zählen zu den kompliziertesten und kunstvollsten Gewölbeformen der [[Gotik]])"}, {"kategorie": "", "text": "Das Netzgewölbe in der [[Michaelerkirche]] ist ein beeindruckendes Beispiel für diese Gewölbeform in Wien. Es zeigt die dekorative Komplexität und den ornamentalen Charakter der spätgotischen Architektur, die für das Netzgewölbe typisch ist."}]'::jsonb, ''),
  ('schdeangwoelb', 'Schdeangwölb', '', '', '', '', 'Sterngewölbe', '[{"kategorie": "arch.", "text": "\"aufwendige Form des [[Kreuzrippengewölbes]], das in der [[Gotik]], insbesondere der [[Spätgotik]], verwendet wurde\""}, {"kategorie": "", "text": "Es zeichnet sich durch die sternförmige Anordnung der [[Rippen]] aus, die sich von den Kreuzungspunkten der Gewölberippen aus in strahlenartigen Mustern über die Gewölbefläche erstrecken"}, {"kategorie": "", "text": "Merkmale des Sterngewölbes: (i) Rippenstruktur (die Rippen sind so angeordnet, dass sie ein symmetrisches, sternartiges Muster bilden. Diese zusätzlichen Rippen schaffen nicht nur Stabilität, sondern dienen auch der dekorativen Wirkung), (ii) dekorativ und funktional (das Sterngewölbe verbindet statische Funktionalität mit künstlerischer Gestaltung, da die Vielzahl der Rippen zur Stabilität beiträgt und gleichzeitig eine kunstvolle Struktur schafft), (iii) Komplexität (die Anordnung der Rippen ist weitaus komplexer als bei einfacheren Gewölbeformen wie dem [[Kreuzrippengewölbe]] oder dem [[Netzgewölbe]]. Oft handelt es sich um besonders prächtige Gewölbe in bedeutenden Kirchen oder repräsentativen Bauten), (iv) gotischer Stil (das Sterngewölbe gehört zur [[Hochgotik]] bzw. [[Spätgotik]] und wurde häufig in Kirchen, Kapellen und Rathäusern verwendet"}, {"kategorie": "", "text": "Ein bemerkenswertes Beispiel für ein Sterngewölbe in Wien ist im [[Stephansdom]] zu finden. Die geometrische Raffinesse des Gewölbes zeigt die hohe Kunstfertigkeit der gotischen Baumeister und verleiht dem Raum eine beeindruckende, fast himmlische Atmosphäre."}]'::jsonb, ''),
  ('hochgotik', 'Hochgotik', '', '', '', '', 'Hochgotik', '[{"kategorie": "arch.", "text": "\"Phase der gotischen Architektur und Kunst, die etwa vom späten 12. bis zum frühen 14. Jahrhundert reicht\""}, {"kategorie": "", "text": "Diese Epoche stellt den Höhepunkt der gotischen Baukunst dar, in der viele der charakteristischen Merkmale der Gotik vollständig ausgebildet und perfektioniert wurden"}, {"kategorie": "", "text": "Merkmale der Hochgotik: (i) [[Spitzbogenarchitektur]] (in der Hochgotik wurde der [[Spitzbogen]], der bereits in der [[Frühgotik]] eingeführt wurde, weiter verfeinert und zum Standard für Fenster, Türen und Gewölbe), (ii) [[Rippengewölbe]] (das [[Kreuzrippengewölbe]] wurde in der Hochgotik perfektioniert. Die [[Rippen]] trugen das Gewicht der Decken und erlaubten größere und höhere Räume), (iii) [[Strebewerk]] (Strebebögen und Strebepfeiler waren charakteristisch für die Hochgotik. Diese Konstruktionen leiteten das Gewicht des Daches nach außen ab und ermöglichten den Bau sehr hoher Kirchen mit dünnen Mauern), (iv) Fenster und Glasmalerei (die Verwendung von großen [[Maßwerkfenstern]] und aufwendigen Glasmalereien nahm in der Hochgotik zu. Kathedralen wurden durch farbenprächtige Rosettenfenster und hohe Fensterwände geprägt), (v) vertikale Betonung (hochgotische Bauten streben visuell in die Höhe. Türme, Fenster und Fassaden sind vertikal ausgerichtet und betonen die himmelstrebende Architektur);  (vi) [[Sakralarchitektur]] (in der Hochgotik wurden viele berühmte Kathedralen Europas erbaut oder erweitert. Diese Gebäude sollten sowohl in ihrer Dimension als auch in ihrer Gestaltung die Erhabenheit des göttlichen Raums widerspiegeln)"}, {"kategorie": "", "text": "In Wien ist die Hochgotik am [[Stephansdom]] zu erkennen, besonders in den Details des Südturms und der Innenarchitektur des Chors."}]'::jsonb, ''),
  ('schbitzbogn', 'Schbitzbogn', '', '', '', '', 'Spitzbogen', '[{"kategorie": "arch.", "text": "\"architektonisches Element, das besonders typisch für die [[gotische]] Baukunst ist\""}, {"kategorie": "", "text": "Im Gegensatz zum [[Rundbogen]], der in der [[Romanik]] vorherrschte, zeichnet sich der Spitzbogen durch zwei kreisbogenförmige Linien aus, die sich oben in einer Spitze treffen"}, {"kategorie": "", "text": "Diese Bogenform ermöglicht eine höhere und schlankere Gestaltung von Toren, Fenstern und Gewölben, was den gotischen Bauten ihr charakteristisches, vertikal ausgerichtetes Erscheinungsbild verleiht"}, {"kategorie": "", "text": "Merkmale des Spitzbogens: vertikale Ausrichtung (der Spitzbogen verstärkt die optische Wirkung der Höhe, was den Eindruck von Leichtigkeit und Himmelsstreben verstärkt, der in der gotischen Architektur besonders wichtig ist), (ii) konstruktive Vorteile (Spitzbögen verteilen das Gewicht der darüber liegenden Bauteile gleichmäßiger auf die Stützelemente, was es ermöglicht, größere Spannweiten und höhere Decken zu bauen, ohne dass massive Mauern erforderlich sind. Dies erlaubte auch größere Fensteröffnungen), (iii) Flexibilität in der Gestaltung (da Spitzbögen in ihrer Form variabel sind (z. B. steiler oder flacher), konnten sie in vielen unterschiedlichen baulichen Situationen eingesetzt werden, von Tür- und Fensteröffnungen bis hin zu [[Gewölben]])"}, {"kategorie": "", "text": "Spitzbögen wurden häufig bei Kirchenfenstern und Eingangsportalen verwendet, besonders in gotischen Kathedralen"}, {"kategorie": "", "text": "Spitzbogengewölbe, wie das [[Kreuzrippengewölbe]], erlaubten eine größere Raumhöhe und aufwendige architektonische Strukturen"}, {"kategorie": "", "text": "[[Der]] Stephansdom ist ein bedeutendes Beispiel für den Einsatz von Spitzbögen in Wien. Besonders an den Fenstern, [[Portalen]] und dem [[Gewölbe]] des Doms ist der Spitzbogen prägend für das gotische Erscheinungsbild."}]'::jsonb, ''),
  ('schbitzbognarchitektua', 'Schbitzbognarchitektua', '', '', '', '', 'Spitzbogenarchitektur', '[{"kategorie": "arch.", "text": "\"Stilmerkmal, das in der Architektur, besonders in der [[Gotik]], weit verbreitet ist\""}, {"kategorie": "", "text": "Der Spitzbogen ist das charakteristische Element dieser Bauweise, bei der Bögen, Fenster, [[Portale]] und [[Gewölbe]] in einer spitzen Form gestaltet sind"}, {"kategorie": "", "text": "Die Spitzbogenarchitektur ermöglicht eine vertikale Betonung von Bauwerken und hat sowohl ästhetische als auch strukturelle Vorteile"}, {"kategorie": "", "text": "Merkmale der Spitzbogenarchitektur: (i) Spitzbogenform (die Bögen laufen nicht rund, sondern spitz zu, was eine höhere und schlankere Form ermöglicht. Dies führt zu einer stärkeren Vertikalisierung der Bauwerke), (ii) gotischer Stil (die Spitzbogenarchitektur ist ein zentrales Element der Gotik, die zwischen dem 12. und 16. Jahrhundert in Europa vorherrschte. Sie findet sich vor allem in Kirchen, Kathedralen und Klöstern), (iii) strukturelle Stabilität: Spitzbögen verteilen das Gewicht besser als [[Rundbögen]] und erlauben dadurch höhere und schlankere Gebäude, große Fensterflächen und eine komplexere Gestaltung von Fassaden und Innenräumen), (iv) Gewölbe und Fenster (neben den Spitzbogenfenstern findet man Spitzbogengewölbe (wie das [[Kreuzrippengewölbe]]), die große Räume überspannen und dabei schlanke, filigrane Stützpfeiler ermöglichen)"}, {"kategorie": "", "text": "Typische Bauwerke der Spitzbogenarchitektur in Wien sind der \n[[Stephansdom]] (besonders in den Fenstern und dem Gewölbe) sowie die [[Votivkirche]] (sowohl außen als auch im Innenraum)"}, {"kategorie": "", "text": "Die Spitzbogenarchitektur verleiht den Gebäuden eine dynamische, nach oben gerichtete Struktur und symbolisiert in der Gotik den Glauben an das Himmlische und das Streben nach Gott."}]'::jsonb, ''),
  ('rundbogn', 'Rundbogn', '', '', '', '', 'Rundbogen', '[{"kategorie": "arch.", "text": "\"architektonisches Element, bei dem der Bogen in einem gleichmäßigen Halbkreis verläuft\""}, {"kategorie": "", "text": "Diese Form des Bogens war ein grundlegendes Konstruktionsprinzip in der Architektur der Antike und des Mittelalters, insbesondere in der [[Romanik]]"}, {"kategorie": "", "text": "Merkmale eines Rundbogens:\n(i) Halbkreisform (der Bogen beschreibt eine perfekte Halbkreisform, wobei seine Höhe die Hälfte seiner Spannweite beträgt. Diese symmetrische Form führt zu einer gleichmäßigen Lastverteilung), (ii) Tragfähigkeit (durch die halbrunde Form leiten Rundbögen das Gewicht der über ihnen liegenden Strukturen effizient zu den seitlichen Stützen oder Pfeilern ab, was sie besonders stabil macht), (iii) Anwendung (Rundbögen werden oft in [[Arkaden]], Fenstern, [[Portalen]] und [[Gewölben]] verwendet und ermöglichen große Öffnungen bei gleichzeitig guter statischer Stabilität"}, {"kategorie": "", "text": "Rundbögen wurden von den Römern perfektioniert und sind ein zentrales Element römischer Baukunst. Sie ermöglichten den Bau großer Aquädukte, Brücken und monumentaler Gebäude"}, {"kategorie": "", "text": "In der [[Romanik]] (11.–13. Jahrhundert) ist der Rundbogen das prägende Element. Kirchen und Kathedralen dieser Epoche, wie die Basilika von Mariazell, verwenden Rundbögen für Fenster, Türen und Gewölbe"}, {"kategorie": "", "text": "Ein typisches Bauwerk mit Rundbögen in Wien ist die [[Ruprechtskirche]], eine der ältesten Kirchen Wiens, die romanische Elemente, darunter auch Rundbögen, in sich vereinigt."}]'::jsonb, ''),
  ('rundbognarchitektua', 'Rundbognarchitektua', '', '', '', '', 'Rundbogenarchitektur', '[{"kategorie": "arch.", "text": "\"Baustil, bei dem der [[Rundbogen]] als prägendes architektonisches Element verwendet wird\""}, {"kategorie": "", "text": "Diese Architekturform ist besonders in der römischen und [[romanischen]] Baukunst weit verbreitet und charakterisiert durch ihre runde, halbbogenförmige Gestaltung von Fenstern, Türen, [[Arkaden]] und [[Gewölben]]"}, {"kategorie": "", "text": "Merkmale der Rundbogenarchitektur: (i) Rundbögen (die zentrale Eigenschaft ist die Verwendung von Rundbögen, die als stabilisierende und dekorative Elemente dienen), (ii) massive Mauern (Gebäude in der Rundbogenarchitektur haben oft dicke, massive Mauern, die das Gewicht der darüber liegenden Strukturen tragen. Die Rundbögen helfen, diese Last auf die Seitenwände abzuleiten), (iii) [[Gewölbe]] (in der Rundbogenarchitektur sind oft [[Tonnengewölbe]] oder [[Kreuzgratgewölbe]] zu finden, die ebenfalls auf dem Prinzip des [[Rundbogens]] beruhen), (iv) schwere Proportionen (die Rundbogenarchitektur ist oft durch eine gewisse Schwere und Massivität der Bauwerke gekennzeichnet, was zu einer eher geschlossenen, blockhaften Erscheinung führt)"}, {"kategorie": "", "text": "Die antiken Römer nutzten Rundbögen in großem Stil, insbesondere für den Bau von Aquädukten, Triumphbögen, Brücken und großen öffentlichen Gebäuden"}, {"kategorie": "", "text": "In der romanischen Architektur (ca. 11.–13. Jahrhundert) spielte der Rundbogen eine zentrale Rolle. Diese Bauweise ist durch Rundbögen bei Fenstern, [[Portalen]] und [[Arkaden]] geprägt und findet sich in vielen romanischen Kirchen und Burgen wieder"}, {"kategorie": "", "text": "In Wien zählt die [[Ruprechtskirche]] (älteste Kirche Wiens) zur Rundbogenarchitektur, zumal sie eine Vielzahl von romanischen Elementen und Rundbögen aufweist"}, {"kategorie": "", "text": "Die Rundbogenarchitektur bildet die Grundlage für viele mittelalterliche Bauten und beeinflusste später auch die [[Neoromanik]] und Teile der [[Renaissance]]."}]'::jsonb, ''),
  ('fruehgotik', 'Frühgotik', '', '', '', '', 'Frühgotik', '[{"kategorie": "arch.", "text": "\"die früheste Phase der gotischen Architektur und Kunst, die im 12. Jahrhundert in Europa, insbesondere in Frankreich, begann und bis etwa zur Mitte des 13. Jahrhunderts andauerte\""}, {"kategorie": "", "text": "Sie markiert den Übergang von der romanischen Bauweise zur [[Gotik]] und zeichnet sich durch bestimmte Merkmale und Stilentwicklungen aus: (i) Spitzbogen (der [[Spitzbogen]] ist ein zentrales architektonisches Element der Gotik, das erstmals in der Frühgotik regelmäßig verwendet wurde. Dieser Bogen löste den [[Rundbogen]] der [[Romanik]] ab und ermöglichte höhere und stabilere Bauwerke), (ii)  Rippengewölbe (in der Frühgotik setzte sich das [[Rippengewölbe]] durch. Es ermöglichte eine effizientere Lastverteilung auf die tragenden Säulen und eröffnete neue Möglichkeiten für hohe, offene Räume), (iii) Strebewerk (das äußere [[Strebewerk]], insbesondere die Strebepfeiler und Strebebögen, wurde in der Frühgotik entwickelt, um den enormen Druck der hohen Wände und [[Gewölbe]] aufzufangen und das Gebäude statisch zu stabilisieren), (iv) Lichtdurchflutung (die Verwendung von [[Spitzbogenfenstern]] und großen Glasflächen ermöglichte es, dass Kirchen mehr natürliches Licht durchflutete. Die Kirchenfenster waren oft mit farbigem Glas ausgestattet, das eine mystische Atmosphäre im Inneren der Kathedralen schuf), (v) Vertikalität (frühgotische Bauwerke streben in die Höhe, was durch die [[Spitzbögen]], [[Rippengewölbe]] und Strebepfeiler unterstützt wird. Diese Vertikalität symbolisiert den geistigen Aufstieg und die Nähe zu Gott)"}, {"kategorie": "", "text": "In Wien zeigt sich die Frühgotik in einigen der bedeutendsten Bauwerke der Stadt, obwohl die Gotik hier generell etwas später Einzug hielt als in Frankreich. Die gotische Architektur prägte Wien vor allem durch ihre Weiterentwicklung zur [[Hochgotik]] und [[Spätgotik]], aber es gibt dennoch Spuren frühgotischer Einflüsse in Wien"}, {"kategorie": "", "text": "Das [[Schottenstift]] wurde im 12. Jahrhundert gegründet und in den folgenden Jahrhunderten mehrfach umgebaut. Während die ursprüngliche Bauweise romanisch war, zeigen spätere Umbauten im 13. Jahrhundert frühgotische Merkmale, vor allem in der Gestaltung des Kircheninneren und der Fenster. Auch hier wird die Entwicklung hin zur [[Gotik]] sichtbar"}, {"kategorie": "", "text": "Der [[Stephansdom]], das wohl berühmteste gotische Bauwerk Wiens, wurde in seiner heutigen Form größtenteils im Hoch- und Spätmittelalter errichtet. Allerdings geht ein Teil der Baugeschichte auf die Frühgotik zurück, insbesondere der Westbau mit den beiden Heidentürmen (13. Jahrhundert). Diese zeigen erste gotische Einflüsse, obwohl sie noch nicht die volle Pracht der späteren [[Hochgotik]] aufweisen."}]'::jsonb, ''),
  ('pilasta', 'Pilasta', '', '', '', '', 'Pilaster', '[{"kategorie": "", "text": "Obwohl ein Pilaster optisch die Form einer Säule nachahmt, ist er meist in die Wand integriert und hat in der Regel keine tragende Funktion"}, {"kategorie": "", "text": "Pilaster dienen in der Architektur vor allem dekorativen Zwecken, um Fassaden zu gliedern oder den Eindruck von Säulenreihen zu erzeugen"}, {"kategorie": "", "text": "Merkmale eines Pilasters: (i) flache Struktur (im Gegensatz zu einer echten Säule ist ein Pilaster nicht freistehend, sondern nur als flacher Streifen Teil der Wand), (ii) Gliederung der Fassade (Pilaster werden häufig verwendet, um große Wandflächen zu unterbrechen und optisch zu strukturieren. Sie verleihen dem Gebäude einen rhythmischen, gegliederten Eindruck), (iii) dekoratives Element (oft ist ein Pilaster mit klassischen architektonischen Details wie Basen, Schäften und [[Kapitellen]] versehen, die an antike Säulenstile (dorisch, ionisch, korinthisch) angelehnt sind), (iv) keine statische Funktion (im Gegensatz zu tragenden Säulen hat ein Pilaster normalerweise keine tragende Funktion. Er dient primär ästhetischen Zwecken)"}, {"kategorie": "", "text": "Pilaster wurden in der römischen Architektur und später in der Renaissance häufig verwendet, um klassische Säulenordnungen nachzuahmen und Wandflächen zu strukturieren"}, {"kategorie": "", "text": "Auch im [[Barock]] und [[Klassizismus]] waren Pilaster beliebt, um Monumentalbauten und Fassaden zu verzieren und harmonische Proportionen zu schaffen"}, {"kategorie": "", "text": "Zusammengefasst ist der Pilaster ein architektonisches Dekorationselement, das die Form einer Säule imitiert, jedoch flach an der Wand liegt und hauptsächlich dazu dient, Fassaden zu gliedern und zu verschönern."}]'::jsonb, ''),
  ('kapitell', 'Kapitell', '', '', '', '', 'Kapitell', '[{"kategorie": "arch.", "text": "\"der obere Abschluss einer Säule, eines Pfeilers oder eines [[Pilasters]], der als Verbindungselement zwischen dem tragenden Schaft und der Last darüber dient, wie etwa einem Architrav oder einem Bogen\""}, {"kategorie": "", "text": "Kapitelle sind nicht nur funktionale Bauteile, sondern auch oft reich verziert und damit ein wichtiges gestalterisches Element in der Architektur"}, {"kategorie": "", "text": "Merkmale eines Kapitells: (i) Übergangselement (das Kapitell bildet den Übergang vom runden oder quadratischen Schaft der Säule zu den waagerechten Bauteilen wie dem Architrav), (ii) Verzierung (Kapitelle sind häufig reich mit dekorativen Motiven geschmückt, die je nach architektonischem Stil variieren. Dazu gehören Pflanzenmotive, figürliche Darstellungen oder geometrische Muster), (iii) tragende Funktion (neben der ästhetischen Bedeutung hat das Kapitell auch eine funktionale Rolle, indem es die Last der über ihm liegenden Bauteile gleichmäßig auf den Säulenschaft verteilt)"}, {"kategorie": "", "text": "In der klassischen Architektur werden Kapitelle typischerweise anhand der Säulenordnung unterschieden: (i) dorisches Kapitell (das einfachste und massivste Kapitell in der klassischen Architektur, das meist aus einer kreisförmigen Platte (Echinus) und einem quadratischen Deckstein (Abakus) besteht und weniger verziert ist, d.h. oft mit klaren, schlichten Formen), (ii) ionisches Kapitell (erkennbar an seinen charakteristischen Voluten (Schneckenformen) an den Seiten, oft feiner und schlanker gestaltet als das dorische Kapitell, mit dekorativen Details, die Eleganz und Leichtigkeit ausstrahlen), (iii) korinthisches Kapitell (aufwendig verziert, meistens mit Akanthusblättern, die den Kapitellkopf schmücken, sehr detailreich und filigran, gilt als die prächtigste Form unter den klassischen Kapitellen)"}, {"kategorie": "", "text": "Auch in anderen Architekturstilen, wie der [[Romanik]], [[Gotik]] oder [[Barock]], spielen Kapitelle eine wichtige Rolle. Sie können figürliche Darstellungen, Blattornamente oder abstrakte Formen enthalten und sind oft an den Stil der jeweiligen Epoche angepasst"}, {"kategorie": "", "text": "Zusammengefasst ist das Kapitell also ein zentrales architektonisches Element, das sowohl eine funktionale als auch eine ästhetische Aufgabe erfüllt, indem es den Schaft einer Säule krönt und den Übergang zu den darüber liegenden Bauelementen schafft."}]'::jsonb, ''),
  ('poatal', 'Poatal', '', '', '', '', 'Portal', '[{"kategorie": "arch.", "text": "\"besonders gestalteter, oft repräsentativer Eingang zu einem Gebäude oder einem Raum\""}, {"kategorie": "", "text": "Das Portal dient sowohl einer praktischen als auch einer symbolischen Funktion und ist häufig kunstvoll gestaltet, vor allem in der Architektur bedeutender Gebäude wie Kirchen, Schlössern oder öffentlichen Gebäuden"}, {"kategorie": "", "text": "Merkmale eines Portals: (i) großer Haupteingang (ein Portal ist in der Regel der Hauptzugang zu einem Bauwerk und oft deutlich größer und auffälliger als andere Türen oder Eingänge), (ii) architektonische Gestaltung (Portale sind oft reich verziert und von architektonischen Elementen wie Bögen, Säulen, Skulpturen oder Reliefs umrahmt. In der [[Gotik]] und [[Romanik]] sind sie häufig mit biblischen Szenen oder symbolischen Darstellungen geschmückt), (iii) symbolische Bedeutung (Portale haben oft eine symbolische Funktion. Sie können den Übergang von der weltlichen in die sakrale oder besondere Sphäre markieren, beispielsweise beim Eintritt in eine Kirche oder Kathedrale)"}, {"kategorie": "", "text": "In Schlössern und Palästen sind Portale oft monumental und repräsentativ gestaltet, um Macht und Reichtum zu symbolisieren. Sie sind häufig mit aufwendigen Skulpturen, Wappen oder Inschriften versehen."}]'::jsonb, ''),
  ('schdrebeweak', 'Schdrebeweak', '', '', '', '', 'Strebewerk', '[{"kategorie": "arch.", "text": "\"architektonisches Konstruktionselement, das in der [[Gotik]] entwickelt wurde, um die hohen Wände und [[Gewölbe]] von Kirchen und Kathedralen statisch zu stabilisieren\""}, {"kategorie": "", "text": "Das Strebewerk besteht aus einer Kombination von Strebepfeilern und Strebebögen und dient dazu, den seitlichen Druck, der durch das Gewicht des Gewölbes entsteht, von den Wänden nach außen abzuleiten und so eine höhere Bauweise zu ermöglichen"}, {"kategorie": "", "text": "Merkmale des Strebewerks: (i) Strebepfeiler (diese massiven, vertikalen Pfeiler stehen außerhalb des Hauptgebäudes und nehmen den Druck auf, der über die Strebebögen von den Wänden weggeleitet wird), (ii) Strebebögen (diese bogenförmigen Elemente verbinden die Wände des Gebäudes mit den Strebepfeilern. Sie verlaufen oft schräg und transportieren die seitliche Last des Gewölbes von den Wänden weg zu den Strebepfeilern), (iii) Funktion (das Strebewerk entlastet die Außenwände von der Last des Gewölbes und ermöglicht es, diese Wände dünner und mit größeren Fenstern zu gestalten. Dadurch konnten die gotischen Kathedralen große Fensterfronten, oft mit farbigem Glas (wie in den berühmten Glasfenstern der gotischen Kathedralen), realisieren), (iv) dekorative Wirkung (neben seiner technischen Funktion wurde das Strebewerk auch zu einem charakteristischen ästhetischen Merkmal der Gotik. Die Strebebögen und -pfeiler sind oft reich verziert, was zur äußeren Monumentalität und Schönheit der gotischen Kirchen beiträgt)"}, {"kategorie": "", "text": "Das Strebewerk war eine der wichtigsten Innovationen der gotischen Architektur. Es ermöglichte den Bau von extrem hohen und lichtdurchfluteten Kathedralen mit großen Fenstern, wie zum Beispiel dem Stephansdom (bei dem Strebepfeiler und Strebebögen deutlich sichtbar sind, insbesondere an den Seiten des Langhauses und des Chors). Ohne das Strebewerk wäre dieses monumentale Bauwerke mit seinen hohen [[Gewölben]] und dünnen Wänden nicht möglich gewesen."}]'::jsonb, ''),
  ('renaissance', 'Renaissance', '', '', '', '', 'Renaissance', '[{"kategorie": "hist.B10900", "text": "\"kulturelle Epoche, die etwa im 14. Jahrhundert in Italien begann und sich bis ins 16. Jahrhundert über Europa ausbreitete\""}, {"kategorie": "", "text": "Sie markiert den Übergang vom Mittelalter zur Neuzeit und ist durch eine Wiederbelebung der antiken Kunst, Kultur und Wissenschaft geprägt"}, {"kategorie": "", "text": "Der Begriff \"Renaissance\" bedeutet \"Wiedergeburt\" und bezieht sich auf das erneute Interesse an den klassischen Idealen der Antike, insbesondere der griechischen und römischen Kultur"}, {"kategorie": "", "text": "Künstler und Architekten der Renaissance orientierten sich an den Formen und Proportionen der Antike. In der Architektur entstanden symmetrische Bauten mit klaren Linien, Rundbögen, Kuppeln und Säulen (z.B. die Peterskirche in Rom). Künstler wie Leonardo da Vinci, Michelangelo und Raffael schufen Werke, die durch naturgetreue Darstellung, Perspektive und menschliche Anatomie gekennzeichnet sind"}, {"kategorie": "", "text": "In Wien gibt es einige bedeutende Bauwerke aus der Renaissance, obwohl die Stadt stärker von barocker Architektur geprägt ist. Dennoch sind einige Bauten und Elemente aus der Renaissance erhalten, die das Stadtbild bereichern, wie zum Beispiel: (i) [[Amalienburg]] (Teil der Wiener Hofburg, wurde im 16. Jahrhundert im Renaissance-Stil erbaut. Sie diente als Wohnsitz von Kaiserin Amalie Wilhelmine, der Witwe von Kaiser [[Joseph]] I. Das Bauwerk zeigt typische Renaissance-Merkmale wie symmetrische Fassaden, klare Linien und dekorative Fensterrahmungen), (ii) [[Schloss]] Neugebäude (am Stadtrand von Wien gelegen, wurde unter Kaiser [[Maximilian]] II. ab 1569 errichtet. Es ist eines der bedeutendsten Beispiele für Renaissancearchitektur in Österreich, inspiriert von italienischen und antiken Vorbildern. Das Schloss zeigt klare, geometrische Formen und wurde ursprünglich als kaiserliche Sommerresidenz geplant. Heute ist es in Teilen erhalten und dient als Veranstaltungsort), (iii) [[Wiener]] Landhaus in der Herrengasse (wurde zwischen 1537 und 1540 erbaut und diente als Sitz der niederösterreichischen Landstände. Die Fassade zeigt typische Renaissanceelemente, wie [[Pilaster]] und reich verzierte [[Gesimse]], die klar und symmetrisch angeordnet sind), (iv) [[Schweizertrakt]] in der Hofburg (einer der ältesten Teile der Wiener Hofburg und wurde im 16. Jahrhundert teilweise im Renaissance-Stil umgebaut. Besonders auffällig sind die reich verzierten Renaissanceportale und die rustizierte Fassade, die der Anlage ein monumentales Aussehen verleiht)"}, {"kategorie": "", "text": "Insgesamt spielte die Renaissance in Wien eine wichtige Rolle, insbesondere in einer Zeit, als die Stadt unter den [[Habsburgern]] zu einem kulturellen Zentrum Europas wurde. Viele der erhaltenen Renaissancebauten oder Umbauten zeigen den Übergang von der [[Spätgotik]] zur Renaissance und prägen noch heute das Stadtbild, obwohl die [[Barockzeit]] später dominiert."}]'::jsonb, ''),
  ('barockzeit', 'Barockzeit', '', '', '', '', 'Barockzeit', '[{"kategorie": "hist.", "text": "\"kulturelle und künstlerische Epoche, die etwa vom späten 16. Jahrhundert bis ins 18. Jahrhundert reichte\""}, {"kategorie": "", "text": "Sie war geprägt von prunkvollen, monumentalen Bauwerken, üppiger Dekoration und einer dynamischen, oft theatralischen Gestaltung von Architektur, Kunst und Musik"}, {"kategorie": "", "text": "Wien wurde während der Barockzeit, insbesondere unter der Herrschaft der [[Habsburger]], zu einem bedeutenden Zentrum des Barockstils in Mitteleuropa"}, {"kategorie": "", "text": "Merkmale der Barockzeit in Wien: (i) prunkvolle Architektur (in Wien entstanden während der Barockzeit zahlreiche prachtvolle Gebäude, darunter Kirchen, Paläste und öffentliche Bauwerke. Sie zeichnen sich durch aufwändige Fassaden, große Kuppeln, reiche Verzierungen und dramatische, oft dynamisch wirkende Gestaltung aus), (ii) Repräsentation von Macht und Glauben (barocke Bauwerke dienten oft dazu, die Macht der Kirche und des Adels, insbesondere der [[Habsburger]] Monarchie, zu demonstrieren. Viele Kirchen und Paläste wurden gebaut, um die Herrlichkeit Gottes und die politische Macht der Herrscher zu unterstreichen), (iii) Bewegung und Dynamik (die barocke Kunst und Architektur betonen Bewegung und Dramatik, was durch den Einsatz von konkaven und konvexen Formen, plastischen Fassaden und reich verzierten Innenräumen erreicht wird. Diese Dynamik spiegelt sich auch in den Fresken und Stuckarbeiten der Gebäude wider), (iv) Raumgestaltung und Gartenkunst (die Raumgestaltung in barocken Bauwerken war oft symmetrisch, mit großen, festlichen Räumen und imposanten Treppenhäusern. Auch die Gartenkunst spielte eine wichtige Rolle, wie in den barocken Schlossgärten, die streng geometrisch angelegt waren)"}, {"kategorie": "", "text": "Zu den bekanntesten Barockbauten in Wien zählen: (i) [[Schloss]] Schönbrunn (errichtet im 17. und 18. Jahrhundert unter Kaiserin Maria Theresia. Es ist ein Symbol der Habsburger Pracht und wurde von Architekten wie Johann Bernhard Fischer von Erlach entworfen), (ii) Karlskirche (eines der herausragenden Beispiele für die barocke Sakralarchitektur in Wien, erbaut von Johann Bernhard Fischer von Erlach und dessen Sohn Joseph Emanuel. Sie kombiniert klassische barocke Elemente wie eine riesige Kuppel, Säulen und aufwändige Stuckverzierungen), (iii) Schloss Belvedere (Meisterwerk der barocken Architektur, entworfen von Johann Lukas von Hildebrandt für Prinz Eugen von Savoyen. Es besteht aus zwei Schlössern (Oberes und Unteres Belvedere), verbunden durch prachtvolle Gärten im französischen Stil), (iv) Peterskirche in der Wiener Innenstadt (weiteres Beispiel für barocke [[Sakralarchitektur]]. Die reiche Innenausstattung, die Kuppel und die Fresken spiegeln den Prunk und die religiöse Bedeutung des Barock wider)"}, {"kategorie": "", "text": "Die [[Habsburger]] spielten eine zentrale Rolle in der Förderung der barocken Architektur und Kunst in Wien. Sie nutzten den Barockstil, um ihre politische Macht und ihre Rolle als Verteidiger des Katholizismus nach außen zu demonstrieren. Die Erfolge der Habsburger in den [[Türkenkriegen]] und ihre führende Position im [[Heiligen]] Römischen Reich spiegelten sich in den monumentalen Bauten und den opulenten Darstellungen von Macht und Herrlichkeit wider"}, {"kategorie": "", "text": "Die Barockzeit in Wien war eine Epoche großer kultureller Blüte, geprägt von prachtvollen Bauten, monumentalen Kirchen und einer künstlerischen Verschmelzung von Architektur, Kunst und Religion. Sie stellte die Macht und den Wohlstand der Habsburger Monarchie zur Schau und trug maßgeblich zur Gestaltung des Wiener Stadtbilds bei, das noch heute stark von der barocken Architektur geprägt ist."}]'::jsonb, ''),
  ('sakralarchitektua', 'Sakralarchitektua', '', '', '', '', 'Sakralarchitektur', '[{"kategorie": "arch.", "text": "\"Hierunter versteht man den Bau und die Gestaltung von religiösen Gebäuden wie Kirchen, Kapellen, Klöstern, Synagogen oder Moscheen, die der Ausübung des Glaubens dienen\""}, {"kategorie": "", "text": "Diese Architektur ist nicht nur funktional, sondern auch symbolisch bedeutungsvoll, da sie den Glauben, die religiösen Rituale und die geistige Atmosphäre widerspiegelt"}, {"kategorie": "", "text": "In Wien hat die Sakralarchitektur über die Jahrhunderte hinweg eine wichtige Rolle gespielt, besonders in Zeiten des katholischen [[Barock]] und der Repräsentation der Habsburger Dynastie"}, {"kategorie": "", "text": "Merkmale der Sakralarchitektur in Wien:\n(i) christlich geprägte Architektur (da Wien historisch stark katholisch geprägt war, dominieren vor allem Kirchen und Kathedralen die Sakralarchitektur. Die Gestaltung dieser Gebäude betont oft religiöse Symbole, Heiligenverehrung und die Pracht des katholischen Glaubens), (ii) architektonische Vielfalt (Wiens Sakralarchitektur zeigt verschiedene architektonische Stile, darunter [[Gotik]], [[Renaissance]], [[Barock]] und [[Klassizismus]]. Jede Epoche brachte spezifische Stilelemente in die Gestaltung der religiösen Gebäude ein), (iii) prächtige Gestaltung (besonders im [[Barock]] wurden sakrale Bauwerke in Wien mit prunkvollen Fassaden, reichen Verzierungen und opulenten Innenräumen versehen, um die Macht und Pracht des Katholizismus zu demonstrieren. Die Innenräume sind häufig mit Fresken, Stuckaturen und Marmor gestaltet)"}, {"kategorie": "", "text": "Bedeutende Sakralbauten in Wien sind: (i) [[Stephansdom]] (Gotik), (ii) [[Karlskirche]] (Barock), (iii) [[Peterskirche]] (Barock), (iv) [[Votivkirche]] (Neugotik), sowie (v) [[Minoritenkirche]] (Gotik und Klassizismus)"}, {"kategorie": "", "text": "In Wien diente die Sakralarchitektur nicht nur als Ort der Gottesdienste, sondern auch als Ausdruck der politischen und religiösen Macht, vor allem unter den Habsburgern. Die prachtvollen Kirchen und Kathedralen waren oft Monumente des Glaubens und des kaiserlichen Einflusses und symbolisierten die enge Verbindung von Kirche und Staat."}]'::jsonb, ''),
  ('schdodtgardia', 'Schdodtgardia', '', '', '', '', 'Stadtguardia', '[{"kategorie": "hist.", "text": "\"militärische Einheit in Wien, die 1569 aus der früheren Tag- und Nachtwache hervorging\""}, {"kategorie": "", "text": "Sie diente vor allem dem Schutz der Stadt und der Überwachung der [[Stadttore]]"}, {"kategorie": "", "text": "Ursprünglich bestanden ihre Mitglieder aus 70 Landsknechten, die von der Stadt Wien bezahlt wurden, ab 1582 jedoch vom Kaiser direkt finanziert wurden und den Status eines kaiserlichen Regiments erhielten"}, {"kategorie": "", "text": "Die Soldaten der Stadtguardia patrouillierten tagsüber und nachts durch die Straßen, mit ihrer Hauptwache am [[Petersplatz]]. Jeder Wachtposten war gut organisiert und mit Soldaten, einem Offizier und oft auch einem [[Trommelschläger]] besetzt. Die Tore wurden sorgfältig verschlossen, und nach der Sperrstunde konnte nur gegen Zahlung eines [[Sperrgeldes]] Zugang zur Stadt gewährt werden"}, {"kategorie": "", "text": "Die Stadtguardia-Soldaten wurden zunächst in Bürgerhäusern oder Wirtshäusern untergebracht, später in eigens errichteten kleinen Häuschen auf den Stadtbasteien. Jeder Soldat musste seine Rüstung und Waffen selbst stellen, und ihre primären Waffen waren [[Musketen]] und [[Hellebarden]]"}, {"kategorie": "", "text": "Im Laufe der Jahre wuchs die Stadtguardia auf bis zu 300 Mann an und wurde auch in den Vorstädten eingesetzt. Im 18. Jahrhundert übernahm sie zudem Aufgaben auf dem neu errichteten [[Linienwall]]"}, {"kategorie": "", "text": "Die Stadtguardia wurde schließlich 1741 unter Kaiserin Maria Theresia aufgelöst, als Wien begann, Kasernen zu bauen und eine dauerhafte Garnison einzurichten. Sie wurde durch die K. k. Militär-Polizeiwache ersetzt, welche die Sicherheitsaufgaben übernahm"}, {"kategorie": "", "text": "Die Stadtguardia war in der Wiener Bevölkerung unbeliebt, da ihre Mitglieder oft Nebenberufe ausübten, um ihren niedrigen Sold aufzubessern, und somit in Konkurrenz zu anderen Gewerbetreibenden standen. Auch ihre Frauen trieben Handel mit Lebensmitteln, was den Unmut der Wiener Bürger zusätzlich verstärkte"}, {"kategorie": "", "text": "Insgesamt spielte die Stadtguardia eine zentrale Rolle im Schutz und in der Verwaltung der Sicherheit Wiens, bevor sie Mitte des 18. Jahrhunderts durch eine reguläre Polizei- und Militärpräsenz ersetzt wurde."}]'::jsonb, ''),
  ('muskeetn', 'Muskeetn', '', '', '', '', 'Muskete', '[{"kategorie": "hist.", "text": "\"frühe Form eines Langgewehrs, das im 16. bis 18. Jahrhundert als Standardfeuerwaffe von Infanteristen verwendet wurde\""}, {"kategorie": "", "text": "Sie ist ein Vorderlader, der durch Zündmechanismen wie das Luntenschloss, Radschloss oder später das Steinschloss gezündet wurde"}, {"kategorie": "", "text": "Die Muskete war im Vergleich zu früheren Handfeuerwaffen präziser und hatte eine größere Reichweite, war jedoch auch schwer und unhandlich, was den Einsatz von Stützen beim Schießen erforderte"}, {"kategorie": "", "text": "Die Muskete war eine typische Waffe für Soldaten im 16. bis 18. Jahrhundert, darunter auch für die [[Stadtguardia]] in Wien. Aufgrund ihrer Unhandlichkeit und langsamen Nachladezeit wurde die Muskete oft in Kombination mit Nahkampfwaffen wie [[Hellebarden]] verwendet"}, {"kategorie": "", "text": "Zusammengefasst war die Muskete eine wichtige Feuerwaffe, die in ihrer Zeit weitverbreitet war und auch in der Bewaffnung der [[Stadtguardia]] eine zentrale Rolle spielte."}]'::jsonb, ''),
  ('hellebardn', 'Hellebardn', '', '', '', '', 'Hellebarde', '[{"kategorie": "hist.", "text": "\"Stangenwaffe, die vor allem vom 14. bis zum 17. Jahrhundert verwendet wurde\" (vom mittelhochdeutschen \"helmbarte\"=\"Hieb- und Stichwaffe\")"}, {"kategorie": "", "text": "Die Hellebarde kombiniert mehrere Funktionen: eine Klinge zum Schneiden und Schlagen, eine Spitze zum Stechen und oft eine Hakenvorrichtung, um Gegner zu ziehen oder zu entwaffnen"}, {"kategorie": "", "text": "Die Hellebarde wurde sowohl in der Infanterie als auch bei Wachtruppen eingesetzt, darunter die Stadtguardia in Wien"}, {"kategorie": "", "text": "Merkmale der Hellebarde: (i) langer Schaft (typisch ist ein langer Holzschaft, etwa 1,5 bis 2 Meter, der eine große Reichweite ermöglichte), (ii) kombinierte Waffenelemente (Axtklinge: Eine breite Klinge diente zum Schlagen und Schneiden), Spitze: Eine scharfe Spitze ermöglichte Stiche gegen gepanzerte Gegner, Haken: Ein Haken auf der Rückseite diente dazu, Reiter vom Pferd zu ziehen oder gegnerische Waffen zu fangen)"}, {"kategorie": "", "text": "Die Hellebarde war vor allem bei Wachen und in der Infanterie beliebt, da sie sowohl im Nah- als auch im Fernkampf vielseitig einsetzbar war"}, {"kategorie": "", "text": "In der [[Stadtguardia]] wurde sie als Schutz- und Wachwaffe eingesetzt, da sie sich gut zur Kontrolle von Menschenmengen und zur Verteidigung der Stadttore eignete"}, {"kategorie": "", "text": "Der Name Hellebarde stammt aus dem Althochdeutschen und setzt sich aus zwei Wörtern zusammen: (i) \"helm\" oder \"halm\" (dieses Wort bedeutet \"Stiel\" oder \"Schaft\" und verweist auf den langen Schaft der Waffe), (ii) \"barte\" (dies ist ein altes Wort für \"Axt\" oder \"Breitaxt\", das auf die scharfe Axtklinge der Hellebarde hinweist). Zusammen beschreibt der Begriff also eine \"Stangenwaffe mit Axtklinge\", die auf einem langen Schaft montiert ist."}]'::jsonb, ''),
  ('romantik', 'Romantik', '', '', '', '', 'Romantik', '[{"kategorie": "hist.", "text": "\"kulturelle und künstlerische Epoche, die sich im späten 18. und im 19. Jahrhundert entwickelte\""}, {"kategorie": "", "text": "Sie entstand als Reaktion auf die rationalen und strengen Ideale der [[Aufklärung]] und der [[Klassik]]"}, {"kategorie": "", "text": "In der Romantik standen Emotionen, Individualität, Naturerlebnisse, das Mystische und die Sehnsucht nach dem Unbekannten im Mittelpunkt"}, {"kategorie": "", "text": "Die Romantik umfasste verschiedene Kunstformen, wie Literatur, Musik, Malerei und Architektur, und betonte das Gefühlsbetonte, das Fantastische und die Rückbesinnung auf das Mittelalter und volkstümliche Traditionen"}, {"kategorie": "", "text": "In Wien war die Romantik vor allem in der Musik und Literatur stark vertreten, während die Architektur weiterhin stark vom [[Klassizismus]] und später dem [[Historismus]] geprägt wurde"}, {"kategorie": "", "text": "Einer der bedeutendsten Vertreter der musikalischen Romantik war Franz Schubert. Seine Lieder und Sinfonien spiegeln die emotionale Tiefe und Naturverbundenheit der Romantik wider. Schuberts Lieder (z.B. \"Die Winterreise\" oder \"Der Erlkönig\") sind Paradebeispiele für die lyrisch-emotionale Ausdruckskraft der Epoche.Vor allem aber [[Johann]] Strauss Sohn trug zur Entwicklung der romantischen Musik bei und prägte mit seinen Walzern das musikalische Wien"}, {"kategorie": "", "text": "In der Wiener Literatur war die Romantik weniger dominant als in Deutschland, aber Autoren wie Franz Grillparzer griffen romantische Themen auf, insbesondere das Verhältnis zwischen Individuum und Schicksal, sowie die emotionale und psychologische Tiefe seiner Figuren"}, {"kategorie": "", "text": "Im Bereich der Architektur orientierte sich Wien im 19. Jahrhundert stärker am Historismus, der gotische und mittelalterliche Formen aufgriff, die auch in der Romantik geschätzt wurden. Ein Beispiel ist die Votivkirche, die im Stil der [[Neugotik]] erbaut wurde und romantische Ideale des Mittelalters widerspiegelt."}]'::jsonb, ''),
  ('aufklaerung', 'Aufklärung', '', '', '', '', 'Aufklärung', '[{"kategorie": "hist.", "text": "\"intellektuelle und kulturelle Bewegung des 17. und 18. Jahrhunderts, die den Schwerpunkt auf Vernunft, Wissenschaft, Bildung und individuelle Freiheit legte\""}, {"kategorie": "", "text": "Sie setzte sich gegen Aberglauben, Absolutismus und kirchliche Autorität zur Wehr und betonte stattdessen den Wert von rationalem Denken und humanitären Idealen"}, {"kategorie": "", "text": "Ziel der Aufklärung war es, durch Wissen und Bildung Fortschritt und Freiheit zu fördern"}, {"kategorie": "", "text": "Merkmale der Aufklärung: (i) Vernunft und Rationalität (die Aufklärung stellte die Vernunft als wichtigstes Mittel zur Erkennung der Wahrheit und zur Verbesserung der Gesellschaft in den Mittelpunkt), (ii) wissenschaftlicher Fortschritt (es gab einen enormen Aufschwung in den Naturwissenschaften, und empirische Forschung wurde gefördert), (iii) individuelle Freiheit und Menschenrechte (die Aufklärung legte großen Wert auf individuelle Freiheiten, Rechte und die Vorstellung, dass alle Menschen gleich geboren sind), (iv) Religionskritik (die Aufklärer forderten eine Trennung von Kirche und Staat und kritisierten religiösen Dogmatismus. Viele Aufklärer förderten den Deismus, die Vorstellung eines Schöpfergottes, der nicht in die Welt eingreift)"}, {"kategorie": "", "text": "In Wien, der Hauptstadt des Habsburgerreiches, spielte die Aufklärung vor allem unter der Herrschaft von Kaiser [[Joseph]] II. eine wichtige Rolle. Er regierte von 1765 bis 1790 und war einer der führenden Vertreter des [[aufgeklärten]] Absolutismus. Seine Reformen standen im Zeichen der Vernunft und sollten das Leben der Bürger verbessern, ohne jedoch die monarchische Ordnung aufzugeben"}, {"kategorie": "", "text": "Josephinische Reformen: (i) Religionspolitik (Joseph II. führte das [[Toleranzpatent]] von 1781 ein, das religiöse Minderheiten wie Protestanten und Juden mehr Rechte gewährte. Gleichzeitig beschränkte er den Einfluss der katholischen Kirche, schloss viele Klöster und förderte eine stärker staatlich kontrollierte Kirche), (ii) Bildungsreformen (Joseph förderte den Aufbau eines staatlich kontrollierten Bildungssystems. Er ließ Schulen gründen, um die allgemeine Bevölkerung zu bilden und den Analphabetismus zu verringern), (iii) Justizreformen (es wurden Gesetze geschaffen, die den Strafvollzug humaner machten. Unter Joseph II. wurde die Folter abgeschafft und das Todesurteil in den meisten Fällen durch mildere Strafen ersetzt), (iv) soziale Reformen (Joseph führte eine Lockerung der Zensur und Maßnahmen zur Verbesserung der Lebensbedingungen der Bauern ein, darunter die Abschaffung der Leibeigenschaft)"}, {"kategorie": "", "text": "Die Wissenschaften erlebten in Wien durch den Einfluss der Aufklärung einen Aufschwung. Universitäten und Akademien förderten das Studium von Naturwissenschaften und Philosophie"}, {"kategorie": "", "text": "In der Kunst und Musik wirkten zur Zeit der Aufklärung in Wien berühmte Persönlichkeiten wie Wolfgang Amadeus Mozart und Joseph Haydn, deren Werke von den Idealen der Aufklärung beeinflusst wurden"}, {"kategorie": "", "text": "Wien erlebte in dieser Zeit die Gründung von [[Lesegesellschaften]], Akademien und Theatern, die das geistige und kulturelle Leben belebten. Diskussionen über Politik, Wissenschaft und Philosophie prägten das intellektuelle Leben der Stadt."}]'::jsonb, ''),
  ('lesegsoeschoftn', 'Lesegsöschoftn', '', '', '', '', 'Lesegesellschaften', '[{"kategorie": "hist.", "text": "\"intellektuelle Zusammenschlüsse, die sich im 18. und 19. Jahrhundert in Wien und ganz Europa bildeten\""}, {"kategorie": "", "text": "Diese Gesellschaften waren Treffpunkte für gebildete Bürger, die an den Ideen der [[Aufklärung]] und am wissenschaftlichen, kulturellen und politischen Austausch interessiert waren"}, {"kategorie": "", "text": "Lesegesellschaften boten Zugang zu Büchern, Zeitschriften und anderen Schriften, die zu dieser Zeit oft schwer verfügbar waren, und förderten Diskussionen über die aktuellen Themen ihrer Zeit"}, {"kategorie": "", "text": "Merkmale von Lesegesellschaften: (i) Zugang zu Wissen und Bildung (Lesegesellschaften betrieben häufig eigene Bibliotheken, in denen Mitglieder Zugang zu Büchern, Zeitungen und Zeitschriften hatten. Diese Sammlungen waren oft umfangreicher als die Bestände privater Haushalte und boten die Möglichkeit, sich über die neuesten wissenschaftlichen, politischen und literarischen Entwicklungen zu informieren), (ii) Diskussionsforen (neben dem Zugang zu Literatur dienten Lesegesellschaften auch als Orte des Austauschs. Hier diskutierten die Mitglieder über aufklärerische Ideen, Philosophie, Politik, Wissenschaft und Kunst), (iii) Förderung des Bürgertums (die Lesegesellschaften waren meist bürgerlich geprägt und boten der aufstrebenden städtischen Mittelschicht eine Plattform, um sich an der intellektuellen und politischen Debatte zu beteiligen. Sie trugen zur Verbreitung aufklärerischer Ideen bei und förderten die gesellschaftliche Bildung und Teilhabe)"}, {"kategorie": "", "text": "Eine der bedeutendsten Lesegesellschaften Wiens war die Gesellschaft der Freunde der Aufklärung, die es sich zur Aufgabe machte, den Austausch und die Verbreitung von Büchern und Wissen zu fördern"}, {"kategorie": "", "text": "Auch in den [[Kaffeehäusern]] Wiens, die als Treffpunkte der städtischen Intelligenz dienten, entstanden spontane Lesegesellschaften, in denen Zeitschriften und Bücher zirkulierten und diskutiert wurden."}]'::jsonb, '')
